INSERT INTO public.llm_cache VALUES ('810d34aa6afc1c6578a0bc6146079fa3cb09fc2b6c4cc7758003800cdf68cdcf', 'evidence_assessment', '{"verdicts":[{"criterion_id":"K1","verdict":"MET","evidence_id":"eb300fc1-1611-43f8-a853-43b62b6c360f","quote":"Annual disaster recovery drill for the core banking system and payment systems. Recovery time objective achieved for all systems tested.","rationale":"The evidence explicitly states that an annual disaster recovery drill was conducted and its results, indicating an implicit report.","confidence":0.9},{"criterion_id":"K2","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"While the evidence mentions test results, it does not provide any information about ''lessons learned documentation''.","confidence":0.8}]}', 'gemini#2', 'gemini-2.5-flash', 461, 313, '2026-10-08 00:24:56.692528+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('14bee398f4f7c2e5039ca64cb56ade2388e17866cd02fee5ae25cbdd305d17ee', 'policy_control_extraction', '{"controls":[{"section_id":"7.1","control_ref":"C-KYC-06","name":"Customer Risk Profile Updation","description":"Customer risk profiles are updated based on their risk level: high risk every two years, medium risk every eight years, and low risk every ten years. Branches complete updation within 60 days of the flag.","frequency_text":"high risk every two years, medium risk every eight years and low risk every ten years","owner":"Head - Retail Operations","control_type":"PREVENTIVE","automation":"MANUAL","source_quote":"high risk every two years, medium risk every eight years and low risk every ten years; branches complete updation within 60 days of the flag. Control reference: C-KYC-06. Owner: Head - Retail Operations."},{"section_id":"8.1","control_ref":"C-KYC-07","name":"Video KYC Session Recording and Storage","description":"Every video KYC session is recorded end-to-end and stored in encrypted storage with access restricted to the KYC team.","frequency_text":null,"owner":"Head - Digital Banking","control_type":"PREVENTIVE","automation":"AUTOMATED","source_quote":"Every video KYC session is recorded end-to-end and stored in encrypted storage with access restricted to the KYC team. Control reference: C-KYC-07. Owner: Head - Digital Banking."},{"section_id":"9.1","control_ref":"C-KYC-08","name":"Record Archiving and Retention","description":"Transaction records and customer identification records are archived and retained for five years from the transaction date or from closure of the relationship, whichever is later.","frequency_text":null,"owner":"Head - IT Operations","control_type":"PREVENTIVE","automation":"AUTOMATED","source_quote":"Transaction records and customer identification records are archived and retained for five years from the transaction date or from closure of the relationship, whichever is later. Control reference: C-KYC-08. Owner: Head - IT Operations."},{"section_id":"10.1","control_ref":"C-KYC-09","name":"Suspicious Transaction Report Filing","description":"Alerts escalated as suspicious are reviewed by the Principal Officer and Suspicious Transaction Reports are filed with the FIU within seven working days of the conclusion. The workflow prevents disclosure to the customer.","frequency_text":null,"owner":"Principal Officer","control_type":"CORRECTIVE","automation":"SEMI_AUTOMATED","source_quote":"Alerts escalated as suspicious are reviewed by the Principal Officer and Suspicious Transaction Reports are filed with the FIU within seven working days of the conclusion; the workflow prevents disclosure to the customer. Control reference: C-KYC-09. Owner: Principal Officer."},{"section_id":"11.1","control_ref":"C-KYC-10","name":"Cash Transaction Report Generation and Submission","description":"Cash Transaction Reports are generated from the core banking system every month and submitted to the FIU before the 15th of the following month.","frequency_text":"every month","owner":"Principal Officer","control_type":"DETECTIVE","automation":"SEMI_AUTOMATED","source_quote":"Cash Transaction Reports are generated from the core banking system every month and submitted to the FIU before the 15th of the following month. Control reference: C-KYC-10. Owner: Principal Officer."},{"section_id":"12.1","control_ref":"C-KYC-11","name":"Automated AML Transaction Monitoring and Alert Investigation","description":"The automated AML system monitors all transactions and generates alerts for unusual patterns. These alerts are investigated and closed within 30 days.","frequency_text":null,"owner":"Head - AML","control_type":"DETECTIVE","automation":"SEMI_AUTOMATED","source_quote":"The automated AML system monitors all transactions and generates alerts for unusual patterns; alerts are investigated and closed within 30 days. Control reference: C-KYC-11. Owner: Head - AML."}]}', 'gemini#2', 'gemini-2.5-flash', 694, 3183, '2026-10-08 00:21:57.180966+00', 1, '2026-10-08 05:36:30.856258+00', NULL);
INSERT INTO public.llm_cache VALUES ('9faafe2a432899a4b0f3e0b15f24bf6742647cb366e50c5ff4c40b0a1aa6aec6', 'policy_control_extraction', '{"controls":[{"section_id":"13.1","control_ref":"C-KYC-12","name":"Annual KYC and AML e-learning for frontline staff","description":"All frontline staff complete KYC and AML e-learning once a year; completion is tracked in the learning management system.","frequency_text":"once a year","owner":"Head - HR Learning","control_type":"PREVENTIVE","automation":"SEMI_AUTOMATED","source_quote":"All frontline staff complete KYC and AML e-learning once a year; completion is tracked in the learning management system. Control reference: C-KYC-12. Owner: Head - HR Learning."},{"section_id":"14.1","control_ref":"C-KYC-13","name":"Quarterly Internal Audit of KYC policy compliance","description":"Internal Audit tests compliance with the KYC policy every quarter on a sample of accounts and reports findings to the Audit Committee.","frequency_text":"every quarter","owner":"Chief Internal Auditor","control_type":"DETECTIVE","automation":"MANUAL","source_quote":"Internal Audit tests compliance with the KYC policy every quarter on a sample of accounts and reports findings to the Audit Committee. Control reference: C-KYC-13. Owner: Chief Internal Auditor."}]}', 'gemini#2', 'gemini-2.5-flash', 400, 1269, '2026-10-08 00:22:04.439092+00', 1, '2026-10-08 05:36:30.87336+00', NULL);
INSERT INTO public.llm_cache VALUES ('04d55afb5686c3f18c79b67ae092dbfad14b2280c7a6eb121c7799b5a745cc1a', 'policy_control_extraction', '{"controls":[{"section_id":"2.1","control_ref":"C-IT-01","name":"Multi-factor authentication for privileged users","description":"Privileged users of critical systems authenticate with multi-factor authentication enforced by the identity provider.","frequency_text":null,"owner":"CISO","control_type":"PREVENTIVE","automation":"AUTOMATED","source_quote":"Privileged users of critical systems authenticate with multi-factor authentication enforced by the identity provider. Control reference: C-IT-01. Owner: CISO."},{"section_id":"3.1","control_ref":"C-IT-02","name":"Review and revoke user access rights","description":"Application owners review user access rights to critical systems every quarter and revoke access that is no longer required.","frequency_text":"every quarter","owner":"CISO","control_type":"DETECTIVE","automation":"MANUAL","source_quote":"Application owners review user access rights to critical systems every quarter and revoke access that is no longer required. Control reference: C-IT-02. Owner: CISO."},{"section_id":"4.1","control_ref":"C-IT-03","name":"Privileged session recording and log retention","description":"All privileged sessions are recorded by the PAM solution and logs are retained for 180 days in the SIEM.","frequency_text":null,"owner":"CISO","control_type":"DETECTIVE","automation":"AUTOMATED","source_quote":"All privileged sessions are recorded by the PAM solution and logs are retained for 180 days in the SIEM. Control reference: C-IT-03. Owner: CISO."},{"section_id":"5.1","control_ref":"C-IT-04","name":"Critical security patch deployment","description":"Critical security patches are deployed to critical systems within 30 days of release through the monthly patch cycle.","frequency_text":"monthly patch cycle","owner":"Head - IT Operations","control_type":"PREVENTIVE","automation":"SEMI_AUTOMATED","source_quote":"Critical security patches are deployed to critical systems within 30 days of release through the monthly patch cycle. Control reference: C-IT-04. Owner: Head - IT Operations."},{"section_id":"6.1","control_ref":"C-IT-05","name":"Disaster recovery drill for critical systems","description":"A disaster recovery drill for critical systems is conducted once a year and the results are reported to the IT Strategy Committee.","frequency_text":"once a year","owner":"Head - IT Operations","control_type":"PREVENTIVE","automation":"MANUAL","source_quote":"A disaster recovery drill for critical systems is conducted once a year and the results are reported to the IT Strategy Committee. Control reference: C-IT-05. Owner: Head - IT Operations."}]}', 'gemini#2', 'gemini-2.5-flash', 594, 2036, '2026-10-08 00:22:16.338955+00', 1, '2026-10-08 05:36:32.492252+00', NULL);
INSERT INTO public.llm_cache VALUES ('b2bc3e70af272421878c3b707eb25a4b25dcd589dc7a5babcd03f85f4312c605', 'policy_control_extraction', '{"controls":[{"section_id":"7.1","control_ref":"C-IT-06","name":"External Vulnerability Assessment and Penetration Testing","description":"An external firm performs vulnerability assessment and penetration testing of all critical systems. Findings are tracked to closure.","frequency_text":"once a year","owner":"CISO","control_type":"DETECTIVE","automation":"SEMI_AUTOMATED","source_quote":"An external firm performs vulnerability assessment and penetration testing of all critical systems once a year; findings are tracked to closure."},{"section_id":"8.1","control_ref":"C-IT-07","name":"Critical Data Backup and Restoration Testing","description":"Critical data is backed up daily; restoration is tested every quarter for a sample of systems.","frequency_text":"daily; restoration is tested every quarter","owner":"Head - IT Operations","control_type":"PREVENTIVE","automation":"AUTOMATED","source_quote":"Critical data is backed up daily; restoration is tested every quarter for a sample of systems."},{"section_id":"9.1","control_ref":"C-IT-08","name":"Cyber Security Incident Reporting to Regulator","description":"The Security Operations Centre classifies incidents and reports cyber security incidents to the regulator within six hours of detection.","frequency_text":"within six hours of detection","owner":"CISO","control_type":"CORRECTIVE","automation":"MANUAL","source_quote":"The Security Operations Centre classifies incidents and reports cyber security incidents to the regulator within six hours of detection."},{"section_id":"10.1","control_ref":"C-IT-09","name":"IT Strategy Committee Meetings","description":"The IT Strategy Committee of the Board meets every quarter; minutes are recorded by the Company Secretary.","frequency_text":"every quarter","owner":"Company Secretary","control_type":"PREVENTIVE","automation":"MANUAL","source_quote":"The IT Strategy Committee of the Board meets every quarter; minutes are recorded by the Company Secretary."},{"section_id":"11.1","control_ref":"C-IT-10","name":"Independent Information Systems Audit","description":"An independent auditor conducts an information systems audit every year and reports to the Audit Committee.","frequency_text":"every year","owner":"Chief Internal Auditor","control_type":"DETECTIVE","automation":"MANUAL","source_quote":"An independent auditor conducts an information systems audit every year and reports to the Audit Committee."}]}', 'gemini#2', 'gemini-2.5-flash', 552, 2368, '2026-10-08 00:22:28.224774+00', 1, '2026-10-08 05:36:32.509404+00', NULL);
INSERT INTO public.llm_cache VALUES ('79b01a100bc645976d50a8428b83dfc0da5ba04aa04cafecbe5853084a446992', 'impact_planning', '{"steps":["extract_obligations","assess_applicability","map_controls","assess_evidence","score_controls","identify_gaps","score_risk","recommend_remediation","impact_report"],"rationale":"Since this is a brand new regulation without existing obligations, we must start by extracting obligations and assessing applicability. With the bank possessing existing controls, we proceed to map controls, assess evidence, and score their effectiveness. Finally, we identify gaps, score associated risks, recommend necessary remediation, and compile the final impact report."}', 'gemini', 'gemini-3.5-flash-lite', 411, 149, '2026-10-08 00:22:40.692188+00', 1, '2026-10-08 05:36:42.27546+00', NULL);
INSERT INTO public.llm_cache VALUES ('68fe4493e215953ea454ac80e83c8fc29c779e8d321e97d9479072439910ea1c', 'applicability', '{"decisions":[{"obligation_id":"5dc39578-c524-4911-8f73-088fd52913f2","decision":"UNCERTAIN","rationale":"The bank profile does not specify if the bank utilizes critical systems.","confidence":0.9},{"obligation_id":"0925ab82-637f-4dfb-8303-71376e95ef1b","decision":"UNCERTAIN","rationale":"The bank profile lacks information regarding the use of critical systems.","confidence":0.9}]}', 'gemini', 'gemini-3.5-flash-lite', 456, 187, '2026-10-08 00:23:27.792004+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('4235b156fb08f37319af68d62a1c7c0d3367ab856db2922a576e89ff0f79cd09', 'obligation_verification', '{"results":[{"candidate_id":"Candidate 0","entailed":true,"reason":"The source text explicitly states that the RE shall constitute an IT Strategy Committee of the Board."},{"candidate_id":"Candidate 1","entailed":true,"reason":"The source text explicitly states that the IT Strategy Committee of the Board shall meet at least once every quarter."},{"candidate_id":"Candidate 2","entailed":true,"reason":"The source text explicitly states that the RE shall appoint a Chief Information Security Officer (CISO)."},{"candidate_id":"Candidate 3","entailed":true,"reason":"The source text explicitly states that the CISO shall report directly to the Executive Director or equivalent."},{"candidate_id":"Candidate 4","entailed":true,"reason":"The source text explicitly states that the RE shall implement multi-factor authentication for all privileged users accessing critical systems."},{"candidate_id":"Candidate 5","entailed":true,"reason":"The source text explicitly states that user access rights to critical systems shall be reviewed at least once every quarter."},{"candidate_id":"Candidate 6","entailed":true,"reason":"The source text explicitly states that privileged access sessions shall be logged."},{"candidate_id":"Candidate 7","entailed":true,"reason":"The source text explicitly states that the logs of privileged access sessions shall be retained for at least 180 days."}]}', 'gemini', 'gemini-3.5-flash-lite', 813, 425, '2026-10-08 00:23:00.686121+00', 1, '2026-10-08 05:36:42.355074+00', NULL);
