INSERT INTO public.llm_cache VALUES ('3addd0099a22981cd4541971532cc534be3da9228dc6d575220fbd0df8e95e51', 'control_mapping', '{"mappings":[{"obligation_id":"obligation 3.1","judgements":[{"control_key":"C-KYC-01","relation":"FULL","coverage":0.95,"confidence":0.98,"control_quote":"approved by the Board of Directors","reason":"The control explicitly states the KYC policy is approved by the Board, satisfying the approval requirement."},{"control_key":"C-KYC-04","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control deals with beneficial‑owner identification, not policy approval."},{"control_key":"C-KYC-13","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control describes an internal audit, not Board approval of the policy."},{"control_key":"C-KYC-03","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control concerns customer due‑diligence at onboarding, not policy approval."}]},{"obligation_id":"obligation 3.2","judgements":[{"control_key":"C-KYC-01","relation":"FULL","coverage":0.95,"confidence":0.98,"control_quote":"placed before the Board for review every year","reason":"The control provides an annual Board review, meeting the at‑least‑once‑a‑year requirement."},{"control_key":"C-KYC-13","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"Quarterly internal audit is not a Board review of the policy."},{"control_key":"C-KYC-12","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"Annual training does not constitute a Board policy review."},{"control_key":"C-KYC-06","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The monthly tracker relates to customer KYC updates, not Board review of the policy."}]},{"obligation_id":"obligation 4.1","judgements":[{"control_key":"C-KYC-02","relation":"FULL","coverage":0.95,"confidence":0.98,"control_quote":"Board designates a Princi