INSERT INTO public.llm_cache VALUES ('6bc2263d020783c9ba80f7f2e39108add7aff01c4cdcad412679ac192df935a2', 'evidence_assessment', '{"verdicts":[{"criterion_id":"K1","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No evidence of a DPO appointment letter or board resolution is provided.","confidence":0.9},{"criterion_id":"K2","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No employment documentation establishing the DPO''s location in India is presented.","confidence":0.9},{"criterion_id":"K3","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No data deletion or purging logs demonstrating erasure within three years are included.","confidence":0.9},{"criterion_id":"K4","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt does not contain a data retention and disposal policy with statutory exceptions.","confidence":0.9},{"criterion_id":"K5","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No approved KYC policy document is shown in the evidence.","confidence":0.9},{"criterion_id":"K6","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"Board minutes approving the policy are not provided.","confidence":0.9},{"criterion_id":"K7","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt describes supported documents but does not present actual KYC records of identification and verification.","confidence":0.9},{"criterion_id":"K8","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"System logs or account opening records confirming CDD at commencement are not included.","confidence":0.9}]}', 'groq', 'openai/gpt-oss-120b', 816, 818, '2026-10-08 00:45:24.037711+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('2d653c693ed858984fb55a29c87a1fef558ebfa0831eb0425b96bc6f3b64cf98', 'remediation', '{"plans":[{"finding_id":"6415a4cd-555e-47f3-b179-1e1d8be883ea","root_cause":"The current control only records video KYC sessions but does not require systematic review, retention policy enforcement, or linkage to the customer due‑diligence record, leaving the V‑CIP obligation only partially satisfied.","actions":[{"kind":"POLICY_UPDATE","description":"Update the Video KYC Policy to mandate that every recorded session be reviewed by the KYC analyst within 48 hours and that the review outcome be logged in the customer’s CDD file."},{"kind":"PROCESS_CHANGE","description":"Add a step in the onboarding workflow to trigger a review task in the V‑CIP platform after recording is stored, with automatic escalation if not completed within the SLA."},{"kind":"TECHNOLOGY_CHANGE","description":"Configure the V‑CIP Platform to enforce encrypted storage retention of 7 years and to generate immutable audit logs linking the recording ID to the customer record."},{"kind":"EVIDENCE_COLLECTION","description":"Produce a quarterly report showing 100 % of new onboarding cases have a completed review entry and retention‑compliant storage metadata."},{"kind":"TESTING","description":"Perform a sample audit of 20 recent onboarding cases to verify review timestamps, linkage to CDD files, and retention settings."},{"kind":"APPROVAL","description":"Obtain sign‑off from Head – Digital Banking and Chief Compliance Officer on the revised policy and workflow changes."}],"suggested_owner":"Head - Digital Banking","target_days":45,"dependencies":["V‑CIP Platform Vendor","IT Security Team"],"expected_evidence":"Revised Video KYC Policy, updated workflow diagram, system configuration screenshots, quarterly review compliance report, audit sample results","verification_method":"Internal compliance audit will re‑run the coverage test and confirm 100 % of V‑CIP obligations are fully documented and reviewed","touches_production":true},{"finding_id":"2f52fbf1-8a57-4518-a259-2fae352413b2","root_cause":"The control verifies identity against documents but lacks a formal document‑authenticity validation process and ongoing monitoring, resulting in only partial coverage of the CDD obligation.","actions":[{"kind":"POLICY_UPDATE","description":"Amend the Customer Due Diligence Policy to require manual verification of document authenticity (e.g., hologram, watermark checks) for all new accounts."},{"kind":"PROCESS_CHANGE","description":"Introduce a dual‑verification step in the Core Banking onboarding workflow: system check followed by analyst visual inspection before account activation."},{"kind":"TECHNOLOGY_CHANGE","description":"Integrate a document‑verification engine (e.g., OCR + fraud detection) into the KYC Portal to flag high‑risk documents for manual review."},{"kind":"EVIDENCE_COLLECTION","description":"Generate a monthly log of all document authenticity checks, including analyst sign‑off and any escalations."},{"kind":"TESTING","description":"Select a random sample of 30 newly opened accounts each quarter to verify that both system and manual checks were performed and documented."},{"kind":"APPROVAL","description":"Secure approval from Compliance / KYC Lead and Head – Retail Operations on the updated workflow and technology integration."}],"suggested_owner":"Compliance / KYC","target_days":30,"dependencies":["KYC Portal Development Team","Risk Management"],"expected_evidence":"Updated CDD Policy, workflow amendment records, configuration of document‑verification engine, monthly authenticity check logs, sample audit report","verification_method":"Quarterly compliance audit will re‑evaluate coverage percentage; the target is 100 % of new accounts with documented manual authenticity verification","touches_production":true}]}', 'groq', 'openai/gpt-oss-120b', 1147, 1164, '2026-10-08 00:45:28.230744+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('a030a4574369786d3a42231113ed17047539c687a9ab686fadfc6a2f1184e483', 'remediation', '{"plans":[{"finding_id":"49b5df62-5cf6-4f1d-b5a0-da89ddf065b5","root_cause":"The AML monitoring control C‑KYC‑11 allows manual exceptions, resulting in alerts not being closed within the mandated 30‑day window and causing the control to be only partially effective.","actions":[{"kind":"CONTROL_CHANGE","description":"Amend control C‑KYC‑11 in the control register to prohibit manual exceptions and state that all alerts must be closed within 30 days without deviation."},{"kind":"PROCESS_CHANGE","description":"Update the AML alert handling SOP to include an automatic escalation step after 20 days of pending status and define clear owner responsibilities."},{"kind":"TECHNOLOGY_CHANGE","description":"Configure the AML System to auto‑escalate any alert older than 20 days to the AML Manager and generate a daily exception report for review."},{"kind":"EVIDENCE_COLLECTION","description":"Collect and archive daily escalation logs and alert closure timestamps for a 90‑day monitoring period."},{"kind":"TESTING","description":"Conduct a quarterly audit sampling 100 alerts to verify that each was closed within the 30‑day deadline."},{"kind":"APPROVAL","description":"Obtain sign‑off from the Head of AML and the Chief Risk Officer on the revised control wording, SOP changes, and system configuration."}],"suggested_owner":"Head of AML (Control Owner)","target_days":45,"dependencies":["IT AML System Team","AML Compliance Team","Risk Management Office"],"expected_evidence":"Updated control register entry for C‑KYC‑11, revised SOP document, AML system configuration screenshot showing escalation rule, archived daily escalation reports, and quarterly audit report confirming 100% closure within 30 days.","verification_method":"Internal audit will re‑run compliance testing using AML system logs and the archived escalation reports for a three‑month period to confirm that no alerts exceed the 30‑day closure window.","touches_production":true}]}', 'groq', 'openai/gpt-oss-120b', 1125, 962, '2026-10-08 00:46:28.970817+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('6eaf90ea9eea245cb357369ddc916803142f864d0b06a390d3bedb82ea35368d', 'control_mapping', '{"mappings":[{"obligation_id":"02d9c7bc-35df-4b1a-b69b-b6517e2da163","judgements":[{"control_key":"C-IT-09","relation":"FULL","coverage":1.0,"confidence":1.0,"control_quote":"The IT Strategy Committee of the Board meets every quarter","reason":"The control describes the activities of an existing IT Strategy Committee of the Board, directly implying its constitution."},{"control_key":"C-IT-05","relation":"FULL","coverage":0.9,"confidence":0.9,"control_quote":"the results are reported to the IT Strategy Committee","reason":"The control indicates that results are reported to the IT Strategy Committee, which implies the committee has been constituted."},{"control_key":"C-IT-10","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"The control refers to an ''Audit Committee'' and an ''information systems audit'', which is not the same as constituting an ''IT Strategy Committee of the Board''."},{"control_key":"C-KYC-13","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"The control describes an audit of KYC policy reported to the Audit Committee, which does not address the constitution of an IT Strategy Committee of the Board."}]},{"obligation_id":"e116fa56-f43f-48f5-8525-12095010ac8e","judgements":[{"control_key":"C-IT-09","relation":"FULL","coverage":1.0,"confidence":1.0,"control_quote":"The IT Strategy Committee of the Board meets every quarter","reason":"The control explicitly states that the IT Strategy Committee of the Board meets every quarter, which fulfills the obligation''s frequency requirement of at least once every quarter."},{"control_key":"C-KYC-13","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"The control describes an internal audit of KYC policy reported to the Audit Committee, which is unrelated to the meeting frequency of the IT Strategy Committee of the Board."},{"control_key":"C-IT-05","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"The control describes an annual disaster recovery drill and does not specify the meeting frequency of the IT Strategy Committee of the Board."},{"control_key":"C-IT-10","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"The control describes an annual independent IS audit reported to the Audit Committee, which is unrelated to the meeting frequency of the IT Strategy Committee of the Board."}]},{"obligation_id":"49bb52c1-771c-4cd2-89d8-b9d8eb3ca178","judgements":[{"control_key":"C-KYC-02","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"The control describes the designation of a Principal Officer for AML, which is a different role from a Chief Information Security Officer (CISO)."},{"control_key":"C-IT-10","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"The control describes an annual independent IS audit and reporting to the Audit Committee, which does not address the appointment of a Chief Information Security Officer (CISO)."},{"control_key":"C-KYC-09","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"The control describes a workflow for filing Suspicious Transaction Reports by a Principal Officer, which is unrelated to the appointment of a Chief Information Security Officer (CISO)."},{"control_key":"C-IT-08","relation":"FULL","coverage":1.0,"confidence":1.0,"control_quote":"owner: CISO","reason":"The control explicitly lists ''CISO'' as the owner, which implies that a Chief Information Security Officer has been appointed."}]}]}', 'gemini#2', 'gemini-2.5-flash', 1248, 3479, '2026-10-08 05:37:57.548356+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('9a53379df242c70a8161e00fb2650c9b6f9864d28d35d9d73986cede24efaa3f', 'remediation', '{"plans":[{"finding_id":"C-KYC-13","root_cause":"The Internal Audit function has not executed the quarterly KYC compliance testing as required by the control definition (P3M). The most recent evidence is 288 days old, indicating a failure in the audit scheduling or execution process, resulting in a control score of 0.422.","actions":[{"kind":"PROCESS_CHANGE","description":"Immediate execution of the overdue KYC compliance test on a representative sample of accounts to generate current evidence and close the 288-day gap."},{"kind":"CONTROL_CHANGE","description":"Update the Internal Audit work plan to explicitly schedule C-KYC-13 testing for the next three quarters (Q1, Q2, Q3) to ensure P3M frequency is met."},{"kind":"EVIDENCE_COLLECTION","description":"Compile the test results, sample selection methodology, and findings report for the immediate test and submit to the Audit Committee."},{"kind":"TESTING","description":"Perform a retrospective review of the last two quarters to identify why the tests were missed and document the root cause of the scheduling failure."}],"suggested_owner":"Chief Internal Auditor","target_days":30,"dependencies":["Internal Audit Team","Audit Committee"],"expected_evidence":"Completed KYC compliance test report for the current quarter, including sample size, findings, and Audit Committee minutes acknowledging receipt.","verification_method":"Compliance will verify the existence of a test report dated within the last 90 days and confirm the next test is scheduled in the audit plan.","touches_production":false},{"finding_id":"C-IT-10","root_cause":"Control C-IT-10 is defined with an annual frequency (P1Y), which is less frequent than the required quarterly (P3M) verification for KYC policy compliance. Additionally, the most recent evidence is 213 days old, indicating the annual cycle has also lapsed or is insufficient for the specific KYC obligation.","actions":[{"kind":"CONTROL_CHANGE","description":"Amend the definition of control C-IT-10 to align with the specific KYC obligation by either splitting it into a dedicated quarterly KYC IT audit control or explicitly mapping a quarterly subset of the IT audit to C-KYC-13."},{"kind":"PROCESS_CHANGE","description":"Update the IT Audit plan to include a specific quarterly review of KYC-related information systems (e.g., data integrity, access controls) to satisfy the P3M requirement."},{"kind":"EVIDENCE_COLLECTION","description":"Conduct an immediate interim review of KYC system controls to generate evidence for the current quarter, bridging the 213-day gap."},{"kind":"POLICY_UPDATE","description":"Update the Internal Audit Charter or IT Audit Policy to clarify that annual IT audits do not satisfy quarterly KYC compliance verification obligations."}],"suggested_owner":"Chief Internal Auditor","target_days":45,"dependencies":["IT Audit Team","Internal Audit Policy Committee"],"expected_evidence":"Updated control definition for C-IT-10, revised IT Audit plan showing quarterly KYC-specific testing, and an interim report covering the current quarter.","verification_method":"Compliance will review the updated control definition and audit plan to confirm P3M frequency is explicitly scheduled for KYC-related IT controls.","touches_production":false}]}', 'groq#2', 'qwen/qwen3.8-27b', 1128, 894, '2026-10-08 00:46:33.261065+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('a08851290b95732681785d867e1e5c0f6385f9fdece38aca3ef8ea5b72705762', 'cluster_confirmation', '{"groups":[{"group_id":"G0","equivalent":false,"topic":"Record retention, deletion, and confidentiality","summary":"This group mixes completely different regulatory requirements including STR disclosure prohibition, customer ID record retention periods, personal data erasure timeframes, log retention limits, and transaction record retention.","shared_control_suggestion":null,"confidence":0.95},{"group_id":"G1","equivalent":false,"topic":"Board governance and policy approval","summary":"The obligations cover different activities such as placing reports before the board, adopting a KYC policy, conducting annual KYC reviews, and nominating a principal officer.","shared_control_suggestion":null,"confidence":0.9},{"group_id":"G2","equivalent":true,"topic":"Periodic staff training","summary":"Both regulations require conducting annual training for staff handling specific regulated duties, though the target audience differs between frontline staff for AML and employees handling personal data for data protection.","shared_control_suggestion":"Implement a unified annual compliance and data protection training program that covers both AML/KYC and data privacy requirements for all applicable personnel.","confidence":0.92},{"group_id":"G3","equivalent":false,"topic":"Periodic audits, testing, and assessments","summary":"This group combines distinct periodic activities such as vulnerability assessments, internal audit verification of KYC, backup restoration testing, and independent information systems audits.","shared_control_suggestion":null,"confidence":0.95},{"group_id":"G4","equivalent":false,"topic":"Regulatory reporting and notifications","summary":"This group contains various external reporting obligations with different triggers, deadlines, and recipients, including STR submissions, CTR submissions, principal officer communications, and data breach notifications.","shared_control_suggestion":null,"confidence":0.98},{"group_id":"G5","equivalent":false,"topic":"Transaction monitoring and access reviews","summary":"This group covers disparate operational controls including user access reviews, automated transaction monitoring systems, and alert review workflows.","shared_control_suggestion":null,"confidence":0.9}]}', 'gemini', 'gemini-3.5-flash-lite', 1245, 590, '2026-10-08 00:47:29.693078+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('d10ecd59b8b46e2e2c616654e170c2fe4c81ec99b7a18d6397dc4ff3c482f0c9', 'conflict_detection', '{"pairs":[{"pair_id":"P0","is_potential_conflict":true,"conflict_type":"DURATION_MISMATCH","reason":"A requires that system and application logs containing personal data be deleted after no more than 90 days, while B requires those same logs be retained for at least 180 days; complying with one would breach the other for the same logs.","resolution_hint":"Seek an explicit exemption or regulatory clarification; if permitted, retain logs for 180 days and document that longer retention is allowed under SRA despite SDPA''s shorter limit.","applicability_overlap":"Both obligations apply to the same system and application logs that contain personal data.","confidence":0.97},{"pair_id":"P1","is_potential_conflict":true,"conflict_type":"SCOPE_OVERLAP","reason":"A limits retention of system and application logs to 90 days, whereas B mandates preserving customer identification records for five years after the relationship ends. If the logs contain those identification records, the two requirements conflict.","resolution_hint":"If the logs serve as identification records, retain them for the five‑year period required by SRA and document that the longer retention satisfies both obligations, or obtain an exemption from SDPA for the extended period.","applicability_overlap":"Both may apply to personal data in logs that include customer identification information.","confidence":0.85},{"pair_id":"P2","is_potential_conflict":true,"conflict_type":"SCOPE_OVERLAP","reason":"B (SDPA) limits log retention to 90 days, while A (SRA) requires preserving customer identification records for five years; when the logs contain those identification records, the obligations conflict.","resolution_hint":"When logs are used as identification records, retain them for the five‑year period required by SRA and seek an SDPA exemption or document that the longer retention is permissible under the higher‑priority rule.","applicability_overlap":"Both obligations could cover the same personal data if the logs store customer identification details.","confidence":0.85}]}', 'groq', 'openai/gpt-oss-120b', 979, 1063, '2026-10-08 00:47:32.253475+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('ba9322ec322cf7d9ce927a8c6ac19db2edcf6c546e2e8ca9b4dee599dcac38c5', 'conflict_detection', '{"pairs":[{"pair_id":"P3","is_potential_conflict":true,"conflict_type":"DURATION_MISMATCH","reason":"A requires that personal data in system and application logs be deleted after 90 days, while B requires that transaction records be retained for at least five years (1825 days). If the logs contain transaction‑related personal data, keeping them for five years would breach A and deleting them after 90 days would breach B.","resolution_hint":"If logs are not considered transaction records, retain separate copies for the five‑year requirement and delete the log copies after 90 days; otherwise apply the longer retention period and document the justification.","applicability_overlap":"Both obligations may apply to personal data that includes transaction information stored in system logs.","confidence":0.85},{"pair_id":"P4","is_potential_conflict":true,"conflict_type":"DURATION_MISMATCH","reason":"A mandates deletion of personal data in logs after 90 days, whereas B mandates retention of transaction records for at least five years (1825 days). Overlap of data types could force a breach of one obligation when complying with the other.","resolution_hint":"Separate the data: keep a retained copy for the five‑year period while deleting the log‑specific copy after 90 days, or rely on the longer retention as the governing requirement where permissible.","applicability_overlap":"Both rules could cover personal data about transactions that is stored in system/application logs.","confidence":0.85},{"pair_id":"P5","is_potential_conflict":false,"conflict_type":"NONE","reason":"A permits erasure of customer data after three years unless another law requires longer retention. B imposes a five‑year retention for identification records, which qualifies as \"another law,\" so complying with B does not violate A.","resolution_hint":null,"applicability_overlap":"Both obligations address post‑relationship customer data, but A’s exception accommodates B’s five‑year retention.","confidence":0.9}]}', 'groq', 'openai/gpt-oss-120b', 997, 1366, '2026-10-08 00:47:35.874493+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('715e7ecb0527b6e764134a46390c33ddf5bbf34410c3ab387624ff664b6824c0', 'conflict_detection', '{"pairs":[{"pair_id":"P6","is_potential_conflict":true,"conflict_type":"DURATION_MISMATCH","reason":"SRA 9.2 mandates preserving customer identification records for ''at least five years after the business relationship has ended'', whereas SDPA 2.1 requires erasing personal data ''no later than three years after the closure of the account''. For a customer whose account is closed, the SRA requirement extends the retention period by two years beyond the SDPA deadline, creating a direct temporal conflict for the same data.","resolution_hint":"SDPA 2.1 contains an explicit exception: ''unless retention is required under any other law for the time being in force''. Since SRA 9.2 is such a law, the SRA retention requirement takes precedence, allowing the entity to retain the data for five years without breaching SDPA 2.1.","applicability_overlap":"Both obligations apply to personal data (customer identification records) associated with a customer whose business relationship or account has ended.","confidence":0.95},{"pair_id":"P7","is_potential_conflict":true,"conflict_type":"DURATION_MISMATCH","reason":"SRA 9.1 requires maintaining transaction records for ''at least five years from the date of transaction'', while SDPA 2.1 mandates erasing personal data ''no later than three years after the closure of the account''. If an account is closed shortly after a transaction, the SDPA erasure deadline (3 years post-closure) may precede the SRA retention deadline (5 years post-transaction), creating a conflict for transaction records containing personal data.","resolution_hint":"SDPA 2.1 includes the clause ''unless retention is required under any other law for the time being in force''. SRA 9.1 constitutes such a law, so the SRA retention period overrides the SDPA erasure deadline for the overlapping data.","applicability_overlap":"Both obligations apply to records of transactions that contain personal data of a customer, particularly in the context of account closure.","confidence":0.9},{"pair_id":"P8","is_potential_conflict":true,"conflict_type":"DURATION_MISMATCH","reason":"SRA 9.1 requires maintaining transaction records for ''at least five years from the date of transaction'', while SDPA 2.1 mandates erasing personal data ''no later than three years after the closure of the account''. If an account is closed shortly after a transaction, the SDPA erasure deadline (3 years post-closure) may precede the SRA retention deadline (5 years post-transaction), creating a conflict for transaction records containing personal data.","resolution_hint":"SDPA 2.1 includes the clause ''unless retention is required under any other law for the time being in force''. SRA 9.1 constitutes such a law, so the SRA retention period overrides the SDPA erasure deadline for the overlapping data.","applicability_overlap":"Both obligations apply to records of transactions that contain personal data of a customer, particularly in the context of account closure.","confidence":0.9}]}', 'groq#2', 'qwen/qwen3.8-27b', 951, 742, '2026-10-08 00:47:37.563011+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('d9d39350aafb6cb35be1354264d497591f35b81741de04f54a7796cb89859e68', 'evidence_assessment', '{"verdicts":[{"criterion_id":"K1","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt does not mention an incident report submitted to the Authority.","confidence":0.95},{"criterion_id":"K2","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No timestamped communication logs with the Authority are referenced.","confidence":0.95},{"criterion_id":"K3","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt lacks any breach notification submissions to the Authority.","confidence":0.95},{"criterion_id":"K4","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"There is no mention of incident response tickets recording breach awareness time.","confidence":0.95}]}', 'groq', 'openai/gpt-oss-120b', 757, 325, '2026-10-08 05:43:58.575211+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('8512ac973104a94d30e5a941aa6ae9bcff79590d137e853631d828235885cacd', 'remediation', '{"plans":[{"finding_id":"3acf219f-14b5-445c-80ae-2f27d50e381d","root_cause":"The AML risk categorisation review (C‑KYC‑05) only covers 75 % of the customer base because the risk scoring engine excludes inactive or low‑value accounts, leading to partial compliance with the six‑month review obligation.","actions":[{"kind":"PROCESS_CHANGE","description":"Update the AML Risk Engine configuration to include all active, inactive, and low‑value customer records in the six‑month risk categorisation run."},{"kind":"TECHNOLOGY_CHANGE","description":"Add an automated scheduler job in the AML Risk Engine to generate a coverage report after each run, flagging any customers not reviewed."},{"kind":"CONTROL_CHANGE","description":"Amend control C‑KYC‑05 documentation to require 100 % coverage and to record the coverage metric in the control log."},{"kind":"EVIDENCE_COLLECTION","description":"Collect and archive the coverage report and updated risk categorisation logs for the next audit cycle."}],"suggested_owner":"Head of AML (Control Owner)","target_days":45,"dependencies":["AML Risk Engine team","Data Management team"],"expected_evidence":"Automated coverage report showing 100 % of customers reviewed and updated risk categorisation records for the period.","verification_method":"Compliance will re‑run the risk assessment coverage check in the next quarterly audit and confirm the control score reaches ≥0.95.","touches_production":true},{"finding_id":"a0166bc6-0def-40a3-bce0-4485b489861c","root_cause":"Internal audit (C‑KYC‑13) has not performed the required quarterly KYC compliance test for 288 days due to missing automated scheduling and lack of oversight, resulting in ineffective control.","actions":[{"kind":"POLICY_UPDATE","description":"Revise the Internal Audit Charter to mandate quarterly KYC compliance testing with a documented deadline."},{"kind":"TECHNOLOGY_CHANGE","description":"Implement a calendar reminder and workflow in the audit management system to trigger a KYC test every 90 days."},{"kind":"PROCESS_CHANGE","description":"Assign a dedicated audit resource to monitor the KYC test schedule and report status to the Chief Internal Auditor."},{"kind":"TESTING","description":"Conduct a retrospective KYC compliance test for the missed periods and document findings."},{"kind":"EVIDENCE_COLLECTION","description":"Archive the test workpapers, sampling methodology, and the completed audit report in the central audit repository."},{"kind":"APPROVAL","description":"Obtain sign‑off from the Audit Committee on the updated schedule and completed retrospective test."}],"suggested_owner":"Chief Internal Auditor","target_days":60,"dependencies":["Audit Management System team","Compliance team"],"expected_evidence":"Signed quarterly KYC test workpapers and audit committee approval memo covering the last 12 months.","verification_method":"Internal audit will provide the next quarterly test evidence; compliance will verify test frequency and completeness against the schedule.","touches_production":false}]}', 'groq', 'openai/gpt-oss-120b', 1126, 1566, '2026-10-08 00:47:26.230979+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('295bb5baf7a338ac020a418da8de23d7df244615bc3a05785fc737be9d6ee4a6', 'conflict_detection', '{"pairs":[{"pair_id":"P9","is_potential_conflict":false,"conflict_type":"NONE","reason":"A requires erasing personal data no later than three years after account closure, while B requires retaining logs for at least 180 days; 180 days is well within the three‑year window, so both obligations can be met simultaneously.","resolution_hint":null,"applicability_overlap":"Both obligations may touch system logs that contain personal data, but the retention periods are compatible.","confidence":0.95},{"pair_id":"P10","is_potential_conflict":false,"conflict_type":"NONE","reason":"A limits retention of system and application logs to a maximum of 90 days, whereas B merely mandates that recordings be stored in a safe and secure manner; the requirements address different dimensions (duration vs security) and do not conflict.","resolution_hint":null,"applicability_overlap":"Both refer to logs/recordings, but one sets a time limit and the other sets a security standard, which can be satisfied together.","confidence":0.94},{"pair_id":"P11","is_potential_conflict":false,"conflict_type":"NONE","reason":"A imposes a 90‑day maximum retention for logs, while B requires secure storage of recordings; the obligations concern different aspects and are not mutually exclusive.","resolution_hint":null,"applicability_overlap":"Both apply to log data, but the duration restriction and security requirement can coexist.","confidence":0.94}]}', 'groq', 'openai/gpt-oss-120b', 941, 752, '2026-10-08 00:48:24.785914+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('41b903e92ab74c11c83f2bcdc66cd5aabf2fdcdb3ba1d8ca63c7439206082921', 'policy_control_extraction', '{"controls":[{"section_id":"2.1","control_ref":"C-KYC-01","name":"KYC and AML Policy Approval and Review","description":"The KYC and AML policy is approved by the Board of Directors and placed before the Board for review every year; the Company Secretary records the approval in Board minutes.","frequency_text":"every year","owner":"Chief Compliance Officer","control_type":"PREVENTIVE","automation":"MANUAL","source_quote":"The KYC and AML policy is approved by the Board of Directors and placed before the Board for review every year; the Company Secretary records the approval in Board minutes. Control reference: C-KYC-01. Owner: Chief Compliance Officer."},{"section_id":"3.1","control_ref":"C-KYC-02","name":"AML Principal Officer Designation and Communication","description":"The Board designates a Principal Officer for AML; Compliance communicates the name and contact details to the FIU within 30 days of any appointment.","frequency_text":"within 30 days of any appointment","owner":"Chief Compliance Officer","control_type":"PREVENTIVE","automation":"MANUAL","source_quote":"The Board designates a Principal Officer for AML; Compliance communicates the name and contact details to the FIU within 30 days of any appointment. Control reference: C-KYC-02. Owner: Chief Compliance Officer."},{"section_id":"4.1","control_ref":"C-KYC-03","name":"Identity Verification for Account Onboarding","description":"The core banking onboarding workflow requires identity verification against officially valid documents before an account number is generated; accounts cannot be activated if CDD is incomplete.","frequency_text":null,"owner":"Head - Retail Operations","control_type":"PREVENTIVE","automation":"SEMI_AUTOMATED","source_quote":"The core banking onboarding workflow requires identity verification against officially valid documents before an account number is generated; accounts cannot be activated if CDD is incomplete. Control reference: C-KYC-03. Owner: Head - Retail Operations."},{"section_id":"5.1","control_ref":"C-KYC-04","name":"Beneficial Owner Identification and Verification for Legal Entities","description":"For legal entity customers, onboarding staff identify beneficial owners holding more than 10% ownership and record them in the KYC Portal; a checker verifies the ownership chart.","frequency_text":null,"owner":"Head - Corporate Operations","control_type":"PREVENTIVE","automation":"MANUAL","source_quote":"For legal entity customers, onboarding staff identify beneficial owners holding more than 10% ownership and record them in the KYC Portal; a checker verifies the ownership chart. Control reference: C-KYC-04. Owner: Head - Corporate Operations."},{"section_id":"6.1","control_ref":"C-KYC-05","name":"Customer Risk Categorisation Review","description":"The AML team reviews the risk categorisation (low, medium, high) of all customers once in six months using the risk scoring engine and documents changes.","frequency_text":"once in six months","owner":"Head - AML","control_type":"DETECTIVE","automation":"SEMI_AUTOMATED","source_quote":"The AML team reviews the risk categorisation (low, medium, high) of all customers once in six months using the risk scoring engine and documents changes. Control reference: C-KYC-05. Owner: Head - AML."}]}', 'gemini#2', 'gemini-2.5-flash', 673, 2201, '2026-10-08 00:21:43.329278+00', 1, '2026-10-08 05:36:30.817706+00', NULL);
