INSERT INTO public.llm_cache VALUES ('8f616dfefe146726b9f48030625c827a68ec0a5664b0c773bfdaa6cfcd19b28e', 'control_mapping', '{"mappings":[{"obligation_id":"17bef97e-e95c-4265-b835-93321f4d4f0d","judgements":[{"control_key":"C-KYC-02","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"This control concerns the designation of a Principal Officer for AML and reporting to the FIU, which does not address the CISO reporting line."},{"control_key":"C-IT-10","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"This control covers annual independent IS audits reporting to the Audit Committee, not the CISO reporting structure to the Executive Director."},{"control_key":"C-IT-08","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"This control addresses reporting cyber incidents to the regulator within six hours, not the CISO internal reporting line."},{"control_key":"C-KYC-09","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"This control addresses STR filing workflows for AML compliance, which is unrelated to the CISO reporting hierarchy."}]},{"obligation_id":"d301e4ae-9c31-43c5-94fe-739d1198b875","judgements":[{"control_key":"C-IT-01","relation":"FULL","coverage":1.0,"confidence":1.0,"control_quote":"Privileged users of critical systems authenticate with multi-factor authentication enforced by the identity provider.","reason":"The control directly enforces multi-factor authentication for privileged users accessing critical systems, fully satisfying scope and requirement."},{"control_key":"C-IT-02","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"This control covers quarterly user access reviews rather than multi-factor authentication implementation."},{"control_key":"C-IT-03","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"This control addresses privileged session recording and log retention, n