INSERT INTO public.llm_cache VALUES ('ef2037eb0ec4bb9152f1123a17abb487bd8385d0dbe316335f11982c48bb1d68', 'control_mapping', '{"mappings":[{"obligation_id":"obligation 3.3 - logging","judgements":[{"control_key":"C-IT-03","relation":"FULL","coverage":0.95,"confidence":1.0,"control_quote":"All privileged sessions are recorded by the PAM solution","reason":"Control logs all privileged sessions continuously, matching the obligation to log privileged access sessions."},{"control_key":"C-IT-02","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"Control describes quarterly user access review, which does not address session logging."},{"control_key":"C-IT-01","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"Control enforces MFA, unrelated to logging privileged sessions."},{"control_key":"C-KYC-07","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"Control records video KYC sessions, not privileged access sessions."}]},{"obligation_id":"obligation 3.3 - retention","judgements":[{"control_key":"C-IT-03","relation":"FULL","coverage":0.95,"confidence":1.0,"control_quote":"logs are retained for 180 days in the SIEM","reason":"Control retains privileged session logs for exactly 180 days, meeting the required minimum retention."},{"control_key":"C-KYC-08","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"Control retains transaction and identification records, not privileged session logs."},{"control_key":"C-IT-02","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"Control describes quarterly access review, which does not address log retention."},{"control_key":"C-IT-01","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"Control enforces MFA, unrelated to log retention."}]},{"obligation_id":"obligation 4.1","judgements":[{"control_key":"C-IT-04","relation":"PARTIAL","coverage":0.5,"confidence":1.0,"control_quote":"Critical security patches are deployed to critical systems within 30 days of release","reason":"Control applies patches within 30 days, which is longer than the required 14‑day deadline, so it only partially satisfies the obligation."},{"control_key":"C-IT-01","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"Control implements MFA, not patch management."},{"control_key":"C-IT-02","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"Control describes quarterly user access review, unrelated to patch deployment."},{"control_key":"C-IT-03","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"Control logs privileged sessions, not patch application."}]}]}', 'groq', 'openai/gpt-oss-120b', 1473, 1343, '2026-10-08 05:38:44.621505+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('9a91156bbd747be8a3dea213231c5b10f6eebd0eb3d7a763197335eb8a1b2a82', 'control_mapping', '{"mappings":[{"obligation_id":"obligation 4.2","judgements":[{"control_key":"C-IT-06","relation":"FULL","coverage":0.95,"confidence":1.0,"control_quote":"An external firm performs vulnerability assessment and penetration testing of all critical systems once a year","reason":"Matches required VA/PT action and annual frequency."},{"control_key":"C-IT-07","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"Control addresses backups, not vulnerability assessment or penetration testing."},{"control_key":"C-IT-05","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"Control describes disaster recovery drill, not VA/PT."},{"control_key":"C-IT-04","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"Control describes patch management, unrelated to VA/PT."}]},{"obligation_id":"obligation 5.1","judgements":[{"control_key":"C-IT-05","relation":"PARTIAL","coverage":0.5,"confidence":1.0,"control_quote":"A disaster recovery drill for critical systems is conducted once a year","reason":"Same drill action but frequency (once a year) is less than required semi‑annual."},{"control_key":"C-IT-07","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"Control covers backup and restore testing, not disaster recovery drills."},{"control_key":"C-IT-04","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"Control is about patch management, unrelated."},{"control_key":"C-IT-02","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"Control addresses user access review, not disaster recovery drills."}]},{"obligation_id":"obligation 5.2","judgements":[{"control_key":"C-IT-07","relation":"FULL","coverage":0.95,"confidence":1.0,"control_quote":"Critical data is backed up daily","reason":"Matches required daily