INSERT INTO public.llm_cache VALUES ('617ddf725e2f1fc15996558c56aa71fce01ea805c2dfcf3172d9873e30912f18', 'control_mapping', '{"mappings":[{"obligation_id":"5.3","judgements":[{"control_key":"C-IT-07","relation":"PARTIAL","coverage":0.7,"confidence":0.95,"control_quote":"restoration is tested every quarter for a sample of systems","reason":"The control matches the required frequency (quarterly) but limits the scope to a ''sample of systems'' rather than testing the restoration of backups generally, making it narrower than the obligation."},{"control_key":"C-KYC-13","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control addresses KYC compliance audits, which is unrelated to backup restoration testing."},{"control_key":"C-IT-02","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control addresses user access reviews, which is unrelated to backup restoration testing."},{"control_key":"C-KYC-06","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control addresses KYC updation tracking, which is unrelated to backup restoration testing."}]},{"obligation_id":"6.1","judgements":[{"control_key":"C-IT-08","relation":"FULL","coverage":1.0,"confidence":0.98,"control_quote":"reports cyber security incidents to the regulator within six hours of detection","reason":"The control explicitly reports cyber security incidents to the regulator within six hours of detection, matching the obligation''s action, scope, and deadline exactly."},{"control_key":"C-IT-04","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control addresses patch management, which is unrelated to incident reporting."},{"control_key":"C-KYC-09","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control addresses Suspicious Transaction Report filing, which is unrelated to cyber security incident reporting."},{"control_key":"C-KYC-11","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control addresses AML transaction monitoring, which is unrelated to cyber security incident reporting."}]},{"obligation_id":"6.2","judgements":[{"control_key":"C-IT-08","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"The control addresses incident classification and reporting to the regulator, but does not mention conducting a root cause analysis."},{"control_key":"C-IT-05","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"The control addresses disaster recovery drills, which are proactive tests, not reactive root cause analyses for critical incidents."},{"control_key":"C-IT-04","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control addresses patch management, which is unrelated to root cause analysis."},{"control_key":"C-KYC-09","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control addresses STR filing, which is unrelated to root cause analysis."}]}]}', 'groq#2', 'qwen/qwen3.8-27b', 1519, 1109, '2026-10-08 05:38:51.932857+00', 0, NULL, NULL);
