INSERT INTO public.llm_cache VALUES ('de512afef22000978cbdc1b803f6e66af6016cbd5c3af432d12404335ee5be52', 'cluster_confirmation', '{"groups":[{"group_id":"G0","equivalent":false,"topic":"System and application log retention period","summary":"The regulations have conflicting retention requirements, with one capping retention at 90 days and the other mandating a minimum of 180 days.","shared_control_suggestion":null,"confidence":0.95},{"group_id":"G1","equivalent":false,"topic":"Appointment of compliance officers","summary":"One regulation requires appointing a Chief Information Security Officer reporting to leadership, while the other requires appointing a Data Protection Officer based in India.","shared_control_suggestion":null,"confidence":0.9}]}', 'gemini', 'gemini-3.5-flash-lite', 358, 132, '2026-10-08 05:45:55.760165+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('3865453b9c800d728aec254f6f14bd58ebe45ffc7d2378e59178e0400ea97c30', 'evidence_assessment', '{"verdicts":[{"criterion_id":"K1","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt provides patch count statistics but no explicit patch management log details.","confidence":0.9},{"criterion_id":"K2","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No system update report is presented in the excerpt.","confidence":0.9},{"criterion_id":"K3","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt does not contain any VA/PT report information.","confidence":0.9},{"criterion_id":"K4","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"There is no evidence of management sign‑off on VA/PT results.","confidence":0.9},{"criterion_id":"K5","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"Disaster recovery drill reports are not referenced in the excerpt.","confidence":0.9},{"criterion_id":"K6","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No test results or lessons learned documentation are provided.","confidence":0.9},{"criterion_id":"K7","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"Backup logs are absent from the excerpt.","confidence":0.9},{"criterion_id":"K8","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt does not include backup schedule information.","confidence":0.9}]}', 'groq', 'openai/gpt-oss-120b', 777, 593, '2026-10-08 05:39:54.056854+00', 1, '2026-10-08 05:51:04.979731+00', NULL);
INSERT INTO public.llm_cache VALUES ('a468947c8c0b12825e5741eb24ad1f94ecc800228916a8e0f4df6a021f605015', 'remediation', '{"plans":[{"finding_id":"424f3800-1373-4f63-b263-35c886aa6b18","root_cause":"Control C‑IT‑03 records privileged sessions but does not address the daily backup obligation; the last backup evidence is 93 days old, indicating no automated backup process.","actions":[{"kind":"POLICY_UPDATE","description":"Update the Data Backup Policy to require daily backups of all critical data and define retention period, referencing obligation 5.2."},{"kind":"TECHNOLOGY_CHANGE","description":"Configure the enterprise Backup System to schedule and execute daily full/incremental backups of all critical data sets, and enable automated success notifications."},{"kind":"CONTROL_CHANGE","description":"Create a new technical control C‑IT‑08 “Critical data is backed up daily” with owner Head – IT Operations and link it to obligation 5.2; deprecate reliance on C‑IT‑03 for backup compliance."},{"kind":"EVIDENCE_COLLECTION","description":"Collect backup job logs and storage reports for the past 30 days to demonstrate daily execution."},{"kind":"TESTING","description":"Perform a restoration test on a representative sample of backed‑up systems and document results in a Restoration Test Report."},{"kind":"APPROVAL","description":"Obtain sign‑off from the CISO and Head – IT Operations that the new control and backup schedule meet the regulatory requirement."}],"suggested_owner":"Head – IT Operations (primary) with CISO as secondary","target_days":45,"dependencies":["Backup System team","SIEM team","IT Operations","Compliance"],"expected_evidence":"Updated Data Backup Policy, Backup System daily schedule screenshot, Control C‑IT‑08 definition, 30‑day backup log archive, Restoration Test Report, Approval sign‑off memo.","verification_method":"Internal audit will review the policy, verify the backup schedule in the Backup System, inspect the 30‑day log archive, and confirm successful restoration test results.","touches_production":true},{"finding_id":"bb349efe-e28b-46d8-9260-97027fd3c414","root_cause":"Control C‑IT‑07 is correctly performing daily backups, but the finding persists because evidence of recent backups was not attached, causing the assessment tool to flag it as ineffective.","actions":[{"kind":"EVIDENCE_COLLECTION","description":"Export backup job logs for the last 30 days from the Backup System and store them in the compliance evidence repository."},{"kind":"PROCESS_CHANGE","description":"Update the control C‑IT‑07 documentation to reference the exported logs as proof of daily backup compliance."},{"kind":"TESTING","description":"Conduct a sample restoration test on a backed‑up system and record the outcome in a Restoration Test Report."},{"kind":"POLICY_UPDATE","description":"Confirm that the Data Backup Policy aligns with control C‑IT‑07 and includes the daily backup requirement."},{"kind":"APPROVAL","description":"Obtain sign‑off from Head – IT Operations and the Compliance Officer that the evidence and documentation satisfy obligation 5.2."}],"suggested_owner":"Head – IT Operations","target_days":20,"dependencies":["Backup System team","Compliance"],"expected_evidence":"30‑day backup log archive, updated C‑IT‑07 control description, Restoration Test Report, updated Data Backup Policy, approval memo.","verification_method":"Compliance audit will verify the presence of the 30‑day logs, review the updated control description, and confirm the restoration test documentation.","touches_production":false}]}', 'groq', 'openai/gpt-oss-120b', 1113, 2131, '2026-10-08 05:40:57.537138+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('b74e21fb3fd1234675de7298cf8fb04e114353500b49ccbce933b5eb0c525747', 'remediation', '{"plans":[{"finding_id":"beb2c4c8-f41a-49bb-bb24-b7d623d27da8","root_cause":"Control C-IT-04 only addresses patch deployment and lacks any mechanism for daily backups; the last control test is 48 days old, so the control is not operating effectively against the backup obligation.","actions":[{"kind":"POLICY_UPDATE","description":"Amend C-IT-04 policy to add a sub‑control that mandates daily backups of all critical data as defined in the data inventory."},{"kind":"TECHNOLOGY_CHANGE","description":"Configure the enterprise backup system to schedule and execute full daily backups for the servers listed in the critical systems register."},{"kind":"PROCESS_CHANGE","description":"Implement a monthly verification process that reviews backup job logs, confirms successful completion, and escalates failures to IT Operations manager."},{"kind":"EVIDENCE_COLLECTION","description":"Export backup job logs for the most recent 30 days and store them in the Compliance Evidence Repository with proper indexing."},{"kind":"TESTING","description":"Perform a control test within 15 days to validate that daily backups occurred and that patch deployment still meets the 30‑day window; record results as new evidence."}],"suggested_owner":"Head - IT Operations","target_days":30,"dependencies":["Backup System Team","Patch Server Team","Change Management Office"],"expected_evidence":"Updated C-IT-04 policy document, backup schedule configuration screenshot, backup logs (last 30 days), patch deployment compliance report, control test results.","verification_method":"Internal audit will review the revised policy, inspect backup logs and patch reports, and re‑run the control test to confirm daily backup compliance and timely patching.","touches_production":true},{"finding_id":"6bca1fab-5530-43fe-9a1c-674bc8a9fdb5","root_cause":"C-IT-04 is ineffective because it does not include a root‑cause‑analysis requirement for critical incidents and the last evidence is 48 days old, leaving the incident‑management obligation unmet.","actions":[{"kind":"PROCESS_CHANGE","description":"Create and publish an RCA procedure that must be executed for every critical incident affecting patched systems, with completion within 5 business days."},{"kind":"CONTROL_CHANGE","description":"Update C-IT-04 to require that a documented RCA be attached to the incident ticket before the control can be marked compliant."},{"kind":"TECHNOLOGY_CHANGE","description":"Enable the incident‑management tool (ServiceNow) to enforce RCA attachment and automatically link it to the corresponding patch record."},{"kind":"EVIDENCE_COLLECTION","description":"Collect RCA reports for the three most recent critical incidents and store them in the Compliance Evidence Repository."},{"kind":"TESTING","description":"Conduct a control test within 20 days to verify that RCAs are completed and recorded for all critical incidents in the test period."}],"suggested_owner":"Head - IT Operations","target_days":45,"dependencies":["Incident Management Team","IT Service Management Tool Vendor","Change Management Office"],"expected_evidence":"Revised C-IT-04 control matrix, RCA procedure document, incident tickets with attached RCA reports, control test report.","verification_method":"Audit will sample incident tickets, confirm RCA attachment and timeliness, and re‑run the control test to ensure the new requirement is enforced.","touches_production":true}]}', 'groq', 'openai/gpt-oss-120b', 1160, 1580, '2026-10-08 05:41:53.861472+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('7b7d984501f6eeea879cac3a2276c79850137ce972857330d01f1651dfddc81e', 'remediation', '{"plans":[{"finding_id":"ec92ed63-2460-4fd9-8f17-aeaffcc0db03","root_cause":"Patch deployment is scheduled monthly (30 days) and the last test is 48 days old, so the control cannot meet the 14‑day obligation for critical patches.","actions":[{"kind":"POLICY_UPDATE","description":"Revise the Patch Management Policy to require that all critical security patches be applied within 14 days of release."},{"kind":"PROCESS_CHANGE","description":"Redesign the patch deployment process to include an emergency patch window that triggers immediate deployment for critical patches."},{"kind":"TECHNOLOGY_CHANGE","description":"Configure the Patch Server automation to prioritize critical patches and enforce a 14‑day deployment schedule."},{"kind":"EVIDENCE_COLLECTION","description":"Collect and archive patch deployment logs for the next 30 days, showing timestamps for each critical patch applied."},{"kind":"TESTING","description":"Perform a control test after 30 days to verify that 100% of critical patches were applied within the 14‑day window."}],"suggested_owner":"Head - IT Operations","target_days":30,"dependencies":["IT Security Team","Change Management Office","Patch Management Tool Vendor"],"expected_evidence":"Updated Patch Management Policy, revised SOP, automated Patch Server configuration snapshot, log archive of patch deployments, test report confirming 14‑day compliance","verification_method":"Internal audit will review the policy, process documentation, system configuration and sample patch logs to confirm all critical patches were applied within 14 days; a follow‑up control test will be executed quarterly","touches_production":true},{"finding_id":"a79edb38-12ad-4b81-91aa-13dffb0e0ba6","root_cause":"Control C‑IT‑04 addresses patching, not incident reporting, leaving the 6‑hour cyber‑security incident reporting obligation uncovered; no dedicated incident‑reporting control exists.","actions":[{"kind":"POLICY_UPDATE","description":"Create an Incident Reporting Policy that mandates reporting of any cyber‑security incident to the Authority within six hours of detection."},{"kind":"PROCESS_CHANGE","description":"Implement an Incident Detection & Reporting workflow with SLA tracking to ensure the six‑hour deadline is met."},{"kind":"TECHNOLOGY_CHANGE","description":"Deploy an automated incident alert system that captures detection timestamps and forwards alerts to the Authority portal within six hours."},{"kind":"CONTROL_CHANGE","description":"Establish new control C‑IR‑01 (Incident Reporting) with frequency Immediate, owner Head - Incident Management, and monitoring via the alert system."},{"kind":"TESTING","description":"Conduct quarterly tabletop exercises and live simulations to verify incidents are reported to the Authority within the six‑hour window."}],"suggested_owner":"Head - Incident Management","target_days":45,"dependencies":["Incident Management Team","Compliance Office","Alerting System Vendor"],"expected_evidence":"Signed Incident Reporting Policy, documented workflow diagram, alert system configuration, control C‑IR‑01 register, exercise reports showing six‑hour reporting compliance","verification_method":"Compliance audit will review the policy, workflow, system logs, and exercise results; a post‑incident review will confirm timestamps of detection and reporting for any real incidents during the audit period","touches_production":true}]}', 'groq', 'openai/gpt-oss-120b', 1180, 1500, '2026-10-08 05:41:57.37686+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('d74fc7f048fc9b890db9712979d926034a0b118e4809eda68934f0e064053a69', 'remediation', '{"plans":[{"finding_id":"196dc80c-d53f-4ec4-8b09-d66de4224864","root_cause":"The control C-IT-01 is defined as operating continuously, but no test records or evidence artifacts have been generated or archived to demonstrate that Multi-Factor Authentication (MFA) is actively enforced by the Identity Provider and PAM systems for privileged users.","actions":[{"kind":"EVIDENCE_COLLECTION","description":"Extract and archive configuration snapshots from the Identity Provider and PAM systems confirming MFA is enabled for all privileged user roles."},{"kind":"TESTING","description":"Perform a sample-based test of privileged user logins to verify that MFA prompts are triggered and successful authentication requires the second factor."},{"kind":"EVIDENCE_COLLECTION","description":"Compile the test results and configuration snapshots into a formal control evidence package for C-IT-01."},{"kind":"APPROVAL","description":"Obtain sign-off from the CISO on the evidence package to confirm the control is operating effectively."}],"suggested_owner":"CISO","target_days":14,"dependencies":["IT Security Team","Identity Provider Admin","PAM System Admin"],"expected_evidence":"Signed-off evidence package containing MFA configuration screenshots and successful MFA login test logs for a sample of privileged users.","verification_method":"Compliance will review the evidence package and independently re-test a random sample of privileged user accounts to confirm MFA enforcement.","touches_production":false},{"finding_id":"d22c071e-29c8-41d2-928f-7014a42387b0","root_cause":"The control C-IT-04 is misaligned with the obligation 5.2. The obligation requires daily backups (P1D), but the control is defined as a monthly patch cycle (P1M). Additionally, the most recent evidence is 48 days old, indicating a failure to meet the required frequency and a lack of recent testing.","actions":[{"kind":"CONTROL_CHANGE","description":"Update the definition of control C-IT-04 to align with obligation 5.2, changing the scope from ''security patches'' to ''critical data backups'' and the frequency from P1M to P1D."},{"kind":"PROCESS_CHANGE","description":"Implement or verify a daily backup job schedule for all critical data systems, ensuring backups are executed and logged every 24 hours."},{"kind":"EVIDENCE_COLLECTION","description":"Generate and archive backup success logs for the last 30 days to demonstrate compliance with the daily frequency requirement."},{"kind":"TESTING","description":"Perform a restore test on a sample of critical data backups to verify integrity and recoverability."},{"kind":"APPROVAL","description":"Obtain sign-off from the Head of IT Operations on the updated control definition and the new backup evidence."}],"suggested_owner":"Head - IT Operations","target_days":30,"dependencies":["IT Operations Team","Backup System Vendor","Data Management Team"],"expected_evidence":"Updated control definition for C-IT-04, 30 days of daily backup success logs, and a successful restore test report.","verification_method":"Compliance will review the updated control definition, audit the backup logs for the last 30 days to confirm daily execution, and witness a restore test.","touches_production":true}]}', 'groq#2', 'qwen/qwen3.8-27b', 1105, 942, '2026-10-08 05:41:59.628721+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('9356e665a35b524b35857cb094de1caf2c8f34bddb736e2242f9f1dbc97e312c', 'remediation', '{"plans":[{"finding_id":"8e71a451-1419-4d4d-852b-17819101e86a","root_cause":"No documented evidence or periodic testing of control C-IT-01, resulting in insufficient evidence that MFA enforcement for privileged users is operating.","actions":[{"kind":"POLICY_UPDATE","description":"Update the IAM Policy to mandate quarterly evidence collection of MFA enforcement for all privileged accounts."},{"kind":"EVIDENCE_COLLECTION","description":"Configure the Identity Provider to generate daily MFA authentication logs and produce a monthly compliance report archived in the security repository."},{"kind":"TESTING","description":"Perform a control test of C-IT-01 within 30 days to verify MFA is enforced for every privileged user login."},{"kind":"PROCESS_CHANGE","description":"Establish a monthly review process in Security Operations to certify MFA logs and close any gaps."},{"kind":"APPROVAL","description":"Obtain sign‑off from the CISO on the new evidence collection schedule, test results, and updated policy."}],"suggested_owner":"CISO","target_days":45,"dependencies":["Identity Provider team","Security Operations"],"expected_evidence":"Monthly MFA compliance report with logs showing successful MFA for all privileged user logins, plus signed test results confirming control operation.","verification_method":"Internal audit will review the monthly reports and test documentation against the MFA control requirement during the next audit cycle.","touches_production":false},{"finding_id":"a3bb601c-d51b-4a31-8998-2ddf430ad669","root_cause":"Patch management does not consistently apply critical security patches within the 30‑day requirement and testing is not performed at the required frequency, leading to an ineffective control.","actions":[{"kind":"PROCESS_CHANGE","description":"Revise the patch management SOP to require critical patches be applied within 7 days and all patches within 30 days, with escalation procedures for missed deadlines."},{"kind":"TECHNOLOGY_CHANGE","description":"Deploy an automated patch compliance monitoring tool integrated with the Patch Server to flag overdue patches in real time."},{"kind":"CONTROL_CHANGE","description":"Add a mid‑month critical‑patch window to the monthly patch cycle to ensure rapid deployment of high‑severity updates."},{"kind":"EVIDENCE_COLLECTION","description":"Generate weekly patch compliance dashboards and retain evidence of installation dates for each critical system."},{"kind":"TESTING","description":"Conduct a control test of C-IT-04 within 14 days to verify that all critical patches were applied within 30 days over the past 90 days."},{"kind":"APPROVAL","description":"Secure approval from the Head of IT Operations on the updated SOP and monitoring tool configuration."}],"suggested_owner":"Head - IT Operations","target_days":60,"dependencies":["Patch Server team","IT Operations","Monitoring/Analytics team"],"expected_evidence":"Automated compliance dashboard showing 100% of critical patches applied within 30 days, signed SOP amendment, and recent control test report confirming effectiveness.","verification_method":"Internal audit will review the compliance dashboard logs, SOP amendment, and control test report during the next compliance audit.","touches_production":true}]}', 'groq', 'openai/gpt-oss-120b', 1150, 1583, '2026-10-08 05:42:54.421083+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('78b765c39aa168700cdaa79932eecbf4878ae66b44c8da2995ee44abdaabcf29', 'impact_planning', '{"steps":["extract_obligations","assess_applicability","map_controls","assess_evidence","score_controls","identify_gaps","score_risk","recommend_remediation","cross_regulation","impact_report"],"rationale":"Because this is a brand new regulation without a previous version, we must first extract and assess the applicability of the new obligations. Since existing controls are present in the system, we then map them, assess evidence, score effectiveness, and identify any compliance gaps. Finally, we score the associated risk, recommend necessary remediation, check for cross-regulatory conflicts, and generate the final impact report."}', 'gemini', 'gemini-3.5-flash-lite', 412, 170, '2026-10-08 00:27:13.393504+00', 1, '2026-10-08 05:42:56.421485+00', NULL);
INSERT INTO public.llm_cache VALUES ('4d4e73f34022e71ad6394428f17a44b6505b4279271fd31f99c960b4cd62ecd8', 'obligation_extraction', '{"obligations":[{"section_id":"2.1","requirement_text":"A data fiduciary must erase customer personal data no later than three years following account closure, except where retention is legally mandated by another law in force.","source_quote":"A data fiduciary shall erase the personal data of a customer no later than three years after the closure of the account, unless retention is required under any other law for the time being in force.","modality":"MUST","obligation_type":"DATA_PROTECTION","subject":"data fiduciary","action":"erase the personal data of a customer","condition":"unless retention is required under any other law for the time being in force","frequency_text":null,"deadline_text":"no later than three years after the closure of the account","applicability":{"entity_types":["bank"],"products":[],"customer_segments":["customer"],"thresholds":[]},"responsible_function":"Data Protection / Operations","required_evidence":[{"description":"Data deletion/purging logs demonstrating erasure within three years of account closure","evidence_type":"system_logs"},{"description":"Data retention and disposal policy documenting statutory exceptions","evidence_type":"policy_document"}],"ambiguity_note":null,"self_confidence":1.0},{"section_id":"2.2","requirement_text":"Personal data found in system and application logs must not be retained for longer than 90 days.","source_quote":"Personal data contained in system and application logs shall not be retained for more than 90 days.","modality":"MUST_NOT","obligation_type":"DATA_PROTECTION","subject":"data fiduciary","action":"retained for more than 90 days","condition":null,"frequency_text":null,"deadline_text":"for more than 90 days","applicability":{"entity_types":["bank"],"products":[],"customer_segments":[],"thresholds":["90 days"]},"responsible_function":"IT / Information Security","required_evidence":[{"description":"Log management configuration demonstrating automatic truncation or deletion of logs older than 90 days","evidence_type":"configuration_file"},{"description":"Audit records of log purging jobs","evidence_type":"audit_log"}],"ambiguity_note":null,"self_confidence":0.95},{"section_id":"3.1","requirement_text":"A data fiduciary must notify the Authority of any personal data breach within 72 hours of becoming aware of the breach.","source_quote":"A data fiduciary shall notify the Authority of any personal data breach within 72 hours of becoming aware of it.","modality":"MUST","obligation_type":"REPORTING","subject":"data fiduciary","action":"notify the Authority of any personal data breach","condition":"within 72 hours of becoming aware of it","frequency_text":null,"deadline_text":"within 72 hours of becoming aware of it","applicability":{"entity_types":["bank"],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":"Incident Response / Data Protection Officer","required_evidence":[{"description":"Breach notification submissions sent to the Authority with timestamps","evidence_type":"regulatory_filing"},{"description":"Incident incident response tickets recording the time of breach awareness","evidence_type":"ticket_log"}],"ambiguity_note":null,"self_confidence":1.0},{"section_id":"4.1","requirement_text":"A data fiduciary must deliver data protection awareness training to all personnel handling personal data at least annually.","source_quote":"A data fiduciary shall conduct data protection awareness training for all employees handling personal data at least once a year.","modality":"MUST","obligation_type":"TRAINING","subject":"data fiduciary","action":"conduct data protection awareness training for all employees handling personal data","condition":null,"frequency_text":"at least once a year","deadline_text":null,"applicability":{"entity_types":["bank"],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":"Human Resources / Data Protection","required_evidence":[{"description":"Training attendance records and completion reports for all relevant staff","evidence_type":"training_records"},{"description":"Training materials and presentation content","evidence_type":"training_materials"}],"ambiguity_note":null,"self_confidence":1.0},{"section_id":"4.2","requirement_text":"A data fiduciary must appoint a Data Protection Officer who is located in India.","source_quote":"A data fiduciary shall appoint a Data Protection Officer who shall be based in India.","modality":"MUST","obligation_type":"GOVERNANCE","subject":"data fiduciary","action":"appoint a Data Protection Officer who shall be based in India","condition":null,"frequency_text":null,"deadline_text":null,"applicability":{"entity_types":["bank"],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":"Board / Senior Management","required_evidence":[{"description":"Formal appointment letter or Board resolution appointing the DPO","evidence_type":"board_resolution"},{"description":"Employment documentation establishing the DPO''s residential/work location in India","evidence_type":"employment_contract"}],"ambiguity_note":null,"self_confidence":1.0}]}', 'gemini#4', 'gemini-3.8-flash', 844, 2378, '2026-10-08 00:27:41.783032+00', 1, '2026-10-08 05:42:56.487446+00', NULL);
INSERT INTO public.llm_cache VALUES ('b4fe191a2b465764736c7f6d7c3cf268e7d525ee7e2e92d2bca6ced278d4957d', 'control_mapping', '{"mappings":[{"obligation_id":"2.1","judgements":[{"control_key":"C-KYC-08","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control retains records for five years, which exceeds the three‑year erasure deadline and does not address erasure at all."},{"control_key":"C-KYC-09","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control concerns STR filing and does not involve data erasure after account closure."},{"control_key":"C-KYC-04","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control deals with beneficial‑owner identification, not with erasing personal data."},{"control_key":"C-KYC-03","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control describes CDD at onboarding and does not address post‑closure data erasure."}]},{"obligation_id":"2.2","judgements":[{"control_key":"C-IT-03","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control retains privileged session logs for 180 days, which is longer than the 90‑day limit."},{"control_key":"C-KYC-08","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control retains transaction and identification records for five years, far exceeding the 90‑day requirement for log data."},{"control_key":"C-IT-02","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control describes quarterly user‑access reviews and does not govern log‑data retention periods."},{"control_key":"C-KYC-09","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control relates to STR filing workflow and does not address retention of system or application logs."}]},{"obligation_id":"3.1","judgements":[{"control_key":"C-KYC-09","relation":"PARTIAL","coverage":0.5,"confidence":0.95,"control_quote":"within seven working days of the conclusion","reason":"The control reports suspicious transaction alerts within seven days, which is longer than the 72‑hour breach‑notification deadline."},{"control_key":"C-IT-08","relation":"PARTIAL","coverage":0.6,"confidence":0.96,"control_quote":"reports cyber security incidents to the regulator within six hours of detection","reason":"The control mandates reporting incidents within six hours, which meets the 72‑hour deadline but limits scope to cyber security incidents rather than all personal data breaches."},{"control_key":"C-KYC-02","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control concerns Principal Officer designation and does not involve breach notification."},{"control_key":"C-KYC-11","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control deals with AML alert closure timelines and does not address breach reporting."}]}]}', 'groq', 'openai/gpt-oss-120b', 1650, 1755, '2026-10-08 05:43:01.602666+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('ca1d3059e0428eb94e98f45a33bf998a1a0bfb817a7b06d88ed8f7d09370f4bb', 'control_mapping', '{"mappings":[{"obligation_id":"4.1","judgements":[{"control_key":"C-KYC-12","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"The control provides KYC/AML training, not data protection awareness training required by the obligation."},{"control_key":"C-IT-06","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"The control describes an annual vulnerability assessment, which does not address training requirements."},{"control_key":"C-IT-07","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"The control concerns backup and restore testing, unrelated to training."},{"control_key":"C-KYC-01","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"The control relates to KYC policy approval and review, not to data protection awareness training."}]},{"obligation_id":"4.2","judgements":[{"control_key":"C-KYC-02","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"The control appoints a Principal Officer for AML, not a Data Protection Officer, and does not specify location in India."},{"control_key":"C-KYC-09","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"The control describes a suspicious transaction reporting workflow, unrelated to DPO appointment."},{"control_key":"C-KYC-03","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"The control concerns customer due diligence at onboarding, not DPO appointment."},{"control_key":"C-KYC-01","relation":"NONE","coverage":0.0,"confidence":1.0,"control_quote":null,"reason":"The control deals with KYC policy approval, not the appointment of a Data Protection Officer."}]}]}', 'groq', 'openai/gpt-oss-120b', 1277, 1370, '2026-10-08 05:43:54.556489+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('f9814d23c6b86287314d85a05e2b6eb8d2e485853dce7d8ec87389af9e6aa19a', 'evidence_assessment', '{"verdicts":[{"criterion_id":"K1","verdict":"MET","evidence_id":"b6173e8e-d58c-4079-ac8e-7967ae052736","quote":"Vulnerability assessment and penetration test of 18 critical systems.","rationale":"The document explicitly references the performance of a vulnerability assessment and penetration test on critical systems.","confidence":0.95},{"criterion_id":"K2","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The provided excerpt does not contain any information regarding management sign-off on the results.","confidence":0.9},{"criterion_id":"K3","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt is a summary of VA/PT findings, not an Information Systems audit report.","confidence":0.9},{"criterion_id":"K4","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No engagement letter or contract with an independent auditor is present in the excerpt.","confidence":0.9},{"criterion_id":"K5","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt contains no records of training attendance or completion reports.","confidence":0.9},{"criterion_id":"K6","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt does not include any training materials or presentation content.","confidence":0.9}]}', 'groq#2', 'qwen/qwen3.8-27b', 715, 509, '2026-10-08 05:44:33.090803+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('38800b5508b47cc34827b64dbe195a336a538a4fad0b6963e1bc55cca7f92313', 'evidence_assessment', '{"verdicts":[{"criterion_id":"K1","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The provided excerpt contains Board minutes regarding policy approval and does not include any training attendance records or completion reports.","confidence":1.0},{"criterion_id":"K2","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The provided excerpt contains Board minutes regarding policy approval and does not include any training materials or presentation content.","confidence":1.0},{"criterion_id":"K3","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The provided excerpt contains Board minutes regarding policy approval and does not include any appointment letter or Board resolution appointing a DPO.","confidence":1.0},{"criterion_id":"K4","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The provided excerpt contains Board minutes regarding policy approval and does not include any employment documentation establishing the DPO''s location.","confidence":1.0}]}', 'groq#2', 'qwen/qwen3.8-27b', 722, 280, '2026-10-08 05:44:33.858237+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('e684b858557e20d19b44f86ae74e9946a80c743700fb7e8d13461af81818c168', 'evidence_assessment', '{"verdicts":[{"criterion_id":"K1","verdict":"MET","evidence_id":"f2eaf179-85ba-412d-8177-d4877c400de5","quote":"Quarterly review of user access rights for 12 critical systems has been completed.","rationale":"The excerpt records that a quarterly access rights review was performed.","confidence":0.9},{"criterion_id":"K2","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No evidence of system logs of privileged access sessions is provided.","confidence":0.7},{"criterion_id":"K3","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt does not address a log retention policy.","confidence":0.7},{"criterion_id":"K4","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No evidence of log storage or retrieval capabilities is mentioned.","confidence":0.7},{"criterion_id":"K5","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"Patch management logs are not referenced in the excerpt.","confidence":0.7},{"criterion_id":"K6","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"System update reports are absent from the provided evidence.","confidence":0.7},{"criterion_id":"K7","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"Disaster recovery drill reports are not included in the excerpt.","confidence":0.7},{"criterion_id":"K8","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"Test results and lessons learned documentation are not mentioned.","confidence":0.7}]}', 'groq', 'openai/gpt-oss-120b', 769, 764, '2026-10-08 05:40:47.824559+00', 1, '2026-10-08 05:44:33.88529+00', NULL);
INSERT INTO public.llm_cache VALUES ('2d422cf7ffe8a9288f11e1cbb70ab0ab5d10d4508471b3bb0a1bbb59adf12b2b', 'remediation', '{"plans":[{"finding_id":"0d1cba6d-6da4-45ee-8665-5293a5a69dd2","root_cause":"The AML monitoring control (C-KYC-11) only generates transaction alerts and does not include a dedicated data‑breach detection or escalation workflow, so breach notifications are not guaranteed within the 72‑hour regulatory deadline.","actions":[{"kind":"POLICY_UPDATE","description":"Revise the Incident Response Policy to embed the 72‑hour breach notification requirement and define escalation steps to the Data Protection Officer."},{"kind":"PROCESS_CHANGE","description":"Create a breach detection process that captures any personal‑data breach event from monitoring tools and automatically raises an incident ticket within 1 hour."},{"kind":"TECHNOLOGY_CHANGE","description":"Configure the AML System (and SIEM) to emit a \"Data Breach\" alert type and integrate it with the incident‑response ticketing platform for immediate DPO notification."},{"kind":"CONTROL_CHANGE","description":"Add a new control C-IR-01 \"Breach Notification Timeliness\" with a KPI of 100% of breaches notified to the Authority within 72 hours."},{"kind":"EVIDENCE_COLLECTION","description":"Collect breach incident logs, ticket timestamps, and notification emails as evidence that the 72‑hour window was met."},{"kind":"APPROVAL","description":"Obtain sign‑off from the Data Protection Officer, Legal, and Head of AML on the updated policy, process, and system configuration."}],"suggested_owner":"Incident Response Lead / Data Protection Officer","target_days":45,"dependencies":["IT Security Team","AML System Team","Legal & Compliance"],"expected_evidence":"Approved Incident Response Policy amendment, breach detection workflow diagram, AML system configuration screenshot, sample incident ticket showing notification within 72 hours.","verification_method":"Conduct a simulated data‑breach drill and verify that an incident ticket is created and the Authority is notified within 72 hours; audit KPI reports for C-IR-01.","touches_production":true},{"finding_id":"c93d4529-6537-4d1e-a8b3-866902f1c201","root_cause":"Control C-KYC-09 focuses on suspicious‑transaction reporting and does not address the statutory requirement to erase personal data three years after account closure, leaving the data‑retention obligation uncovered.","actions":[{"kind":"POLICY_UPDATE","description":"Amend the Data Retention Policy to state that personal data must be permanently deleted no later than three years after account closure, unless a longer retention is legally required."},{"kind":"PROCESS_CHANGE","description":"Establish a data‑lifecycle process that flags closed accounts approaching the three‑year mark and queues them for deletion."},{"kind":"TECHNOLOGY_CHANGE","description":"Implement an automated purge job in the CRM/Data Warehouse that deletes personal data for accounts closed >3 years, with audit‑log generation."},{"kind":"CONTROL_CHANGE","description":"Create control C-DP-03 \"Data Erasure Compliance\" to monitor deletion job success and quarterly review of retention reports."},{"kind":"EVIDENCE_COLLECTION","description":"Gather deletion job logs, retention reports, and sample records showing successful erasure after the three‑year threshold."},{"kind":"TESTING","description":"Perform quarterly test runs selecting random closed accounts to verify that the automated purge correctly removes personal data."}],"suggested_owner":"Data Protection Officer / Operations Manager","target_days":60,"dependencies":["IT Data Management Team","CRM System Team","Legal"],"expected_evidence":"Updated Data Retention Policy, automated purge job script, audit logs of deletions, quarterly retention compliance report.","verification_method":"Independent audit queries the database to confirm no personal data exists for accounts closed >3 years; review C-DP-03 KPI dashboard for 100% deletion compliance.","touches_production":true}]}', 'groq', 'openai/gpt-oss-120b', 1178, 1718, '2026-10-08 05:45:02.793841+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('bb46c22bd05135bd0a23c3878150645145c4c421b56dd8756dbf189d02893655', 'remediation', '{"plans":[{"finding_id":"0f2899d2-f1ee-45f4-88bc-657144f8d2a2","root_cause":"Control C-IT-03 retains logs for 180 days, which exceeds the 90-day retention limit for personal data specified in obligation 2.2. The control configuration does not distinguish between general security logs and logs containing personal data, leading to non-compliant retention of sensitive information.","actions":[{"kind":"CONTROL_CHANGE","description":"Modify the SIEM retention policy for log sources identified as containing personal data to enforce a 90-day maximum retention period, overriding the default 180-day setting."},{"kind":"TECHNOLOGY_CHANGE","description":"Implement automated data classification or masking rules in the log ingestion pipeline to identify and flag logs containing personal data before storage."},{"kind":"POLICY_UPDATE","description":"Update the Information Security Policy to explicitly state that logs containing personal data must be purged or anonymized after 90 days, aligning with obligation 2.2."},{"kind":"TESTING","description":"Perform a verification test to confirm that logs containing personal data are automatically deleted or anonymized after 90 days in the SIEM environment."}],"suggested_owner":"CISO / IT Information Security","target_days":30,"dependencies":["SIEM Vendor Support","Data Protection Officer"],"expected_evidence":"Updated SIEM retention configuration screenshots, policy document revision, and test report confirming 90-day purge of personal data logs.","verification_method":"Compliance team will query the SIEM for logs older than 90 days containing personal data markers and verify they are no longer present or are anonymized.","touches_production":true},{"finding_id":"99fd27cd-4416-4c22-95e8-59fa1d01d6ce","root_cause":"Control C-IT-06 is mapped to vulnerability assessment and penetration testing, which does not address the obligation for annual data protection awareness training. The control is ineffective for this obligation because it covers a different domain (security testing vs. employee training), resulting in a mismatch between the control and the requirement.","actions":[{"kind":"PROCESS_CHANGE","description":"Decouple C-IT-06 from obligation 4.1 and assign a new or existing control specifically dedicated to data protection awareness training for employees handling personal data."},{"kind":"POLICY_UPDATE","description":"Update the Data Protection Policy to mandate annual training for all employees handling personal data, with clear ownership by HR and Data Protection teams."},{"kind":"EVIDENCE_COLLECTION","description":"Collect training completion records from the Learning Management System (LMS) for the current year to demonstrate compliance with the annual training requirement."},{"kind":"TESTING","description":"Verify that 100% of employees handling personal data have completed the required data protection awareness training within the last 12 months."}],"suggested_owner":"Human Resources / Data Protection Officer","target_days":45,"dependencies":["Learning Management System (LMS) Team","IT Department"],"expected_evidence":"Updated control mapping document, training completion reports from LMS, and revised Data Protection Policy.","verification_method":"Compliance team will review LMS records to confirm all relevant employees have completed training within the required timeframe and verify the control mapping is corrected.","touches_production":false}]}', 'groq#2', 'qwen/qwen3.8-27b', 1092, 921, '2026-10-08 05:45:04.860166+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('167c8916ed8bc9aee6bde7ba50b9998ae6f1faf758cbdaeb5345bf2df90fbae8', 'remediation', '{"plans":[{"finding_id":"90575ccb-802d-4c12-8392-4223a57689d8","root_cause":"The existing control C-KYC-02 addresses AML principal officer appointments, not the regulatory requirement to appoint a Data Protection Officer (DPO) based in India, resulting in a mis‑aligned control and partial coverage of the governance obligation.","actions":[{"kind":"POLICY_UPDATE","description":"Amend the Data Governance Policy to explicitly require the appointment of a Data Protection Officer who is resident in India and define the DPO’s responsibilities."},{"kind":"CONTROL_CHANGE","description":"Create a new control C-PRIV-01: \"Appoint Data Protection Officer based in India and maintain up‑to‑date contact details in the regulatory register\" and assign ownership to the Chief Compliance Officer."},{"kind":"PROCESS_CHANGE","description":"Establish a Board approval process for DPO appointments and a compliance process to notify the regulator within 30 days of any change."},{"kind":"EVIDENCE_COLLECTION","description":"Gather the DPO appointment letter, proof of Indian residence (e.g., address verification), and update the control register with the DPO’s details."},{"kind":"APPROVAL","description":"Secure Board and Senior Management sign‑off on the revised policy, new control C-PRIV-01, and the updated control register."},{"kind":"TESTING","description":"Schedule an internal audit test to verify the DPO appointment, residency proof, and that the control register reflects current information."}],"suggested_owner":"Chief Compliance Officer (Compliance Function)","target_days":45,"dependencies":["Legal Department","Human Resources","IT Systems (Regulatory Register)"],"expected_evidence":"Updated Data Governance Policy, control register entry for C-PRIV-01 with DPO appointment letter and Indian residence proof, Board approval minutes.","verification_method":"Compliance audit review of policy, control register, and DPO documentation; confirm regulator notification log within 30 days of appointment.","touches_production":false}]}', 'groq', 'openai/gpt-oss-120b', 905, 816, '2026-10-08 05:45:54.291914+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('57263739b6e76002293c7fd47d6d6e2a052c617275de1538045746f7e9b66895', 'conflict_detection', '{"pairs":[{"pair_id":"P0","is_potential_conflict":true,"conflict_type":"MODALITY_CONFLICT","reason":"A requires that personal data in system and application logs shall NOT be retained for more than 90 days (must delete after 90 days), while B requires that the logs shall be retained for at least 180 days (must keep). The same logs cannot simultaneously satisfy both requirements.","resolution_hint":"If the jurisdiction providing the 180‑day requirement includes an explicit exemption clause for shorter retention limits, that clause could be relied upon; otherwise a legal exemption or amendment is needed to reconcile the contradictory mandates.","applicability_overlap":"Both obligations apply to the same system and application logs containing personal data.","confidence":0.97},{"pair_id":"P1","is_potential_conflict":false,"conflict_type":"NONE","reason":"A mandates retaining logs for at least 180 days. B mandates erasing personal data no later than three years after account closure, but expressly allows a longer retention period when required by another law. The 180‑day requirement can be treated as that other law, so compliance with A does not breach B.","resolution_hint":null,"applicability_overlap":"Both obligations concern personal data in customer logs, but the longer‑retention exception in B prevents a conflict.","confidence":0.95}]}', 'groq', 'openai/gpt-oss-120b', 855, 778, '2026-10-08 05:45:57.879363+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('49bf53586937881c0eb754032a091568539346085ca13044af9120fd3e34b185', 'impact_planning', '{"steps":["extract_obligations","assess_applicability","map_controls","assess_evidence","score_controls","identify_gaps","score_risk","recommend_remediation","cross_regulation","impact_report"],"rationale":"For this new regulation with existing controls, we must first extract obligations and assess applicability before mapping them to controls. Once mapped, we assess evidence, score controls, identify and score gaps, recommend remediation, check cross-regulation impacts, and finally generate the impact report."}', 'gemini', 'gemini-3.5-flash-lite', 412, 116, '2026-10-08 00:29:04.291849+00', 1, '2026-10-08 05:46:04.291101+00', NULL);
INSERT INTO public.llm_cache VALUES ('6e9e1d66a617a4976bee5401fabbb02e75dd8647d19317d076bb469e50355eae', 'obligation_extraction', '{"obligations":[{"section_id":"3.1","requirement_text":"Regulated Entity must have a KYC policy approved by its Board of Directors.","source_quote":"Every RE shall have a Know Your Customer (KYC) policy duly approved by its Board of Directors.","modality":"MUST","obligation_type":"GOVERNANCE","subject":"Regulated Entity","action":"have a Know Your Customer (KYC) policy duly approved by its Board of Directors","condition":null,"frequency_text":null,"deadline_text":null,"applicability":{"entity_types":["scheduled commercial bank","small finance bank"],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":null,"required_evidence":[{"description":"Approved KYC policy document","evidence_type":"DOCUMENT"},{"description":"Board minutes approving the policy","evidence_type":"DOCUMENT"}],"ambiguity_note":null,"self_confidence":0.99},{"section_id":"3.2","requirement_text":"Board must review the KYC policy at least once a year.","source_quote":"The KYC policy shall be reviewed by the Board at least once a year.","modality":"MUST","obligation_type":"GOVERNANCE","subject":"Board of Directors","action":"review the KYC policy","condition":null,"frequency_text":"at least once a year","deadline_text":null,"applicability":{"entity_types":["scheduled commercial bank","small finance bank"],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":null,"required_evidence":[{"description":"Board meeting minutes showing review","evidence_type":"DOCUMENT"},{"description":"Updated KYC policy reflecting review","evidence_type":"DOCUMENT"}],"ambiguity_note":null,"self_confidence":0.98},{"section_id":"4.1","requirement_text":"Regulated Entity must nominate a Principal Officer.","source_quote":"The RE shall nominate a Principal Officer","modality":"MUST","obligation_type":"GOVERNANCE","subject":"Regulated Entity","action":"nominate a Principal Officer","condition":null,"frequency_text":null,"deadline_text":null,"applicability":{"entity_types":["scheduled commercial bank","small finance bank"],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":null,"required_evidence":[{"description":"Appointment letter of Principal Officer","evidence_type":"DOCUMENT"},{"description":"Internal record of nomination","evidence_type":"DOCUMENT"}],"ambiguity_note":null,"self_confidence":0.97},{"section_id":"4.1","requirement_text":"Principal Officer must ensure compliance.","source_quote":"shall be responsible for ensuring compliance","modality":"MUST","obligation_type":"GOVERNANCE","subject":"Principal Officer","action":"ensure compliance","condition":null,"frequency_text":null,"deadline_text":null,"applicability":{"entity_types":[],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":null,"required_evidence":[{"description":"Compliance reports signed by Principal Officer","evidence_type":"DOCUMENT"}],"ambiguity_note":null,"self_confidence":0.95},{"section_id":"4.1","requirement_text":"Principal Officer must monitor transactions.","source_quote":"shall be responsible for ... monitoring transactions","modality":"MUST","obligation_type":"MONITORING","subject":"Principal Officer","action":"monitor transactions","condition":null,"frequency_text":null,"deadline_text":null,"applicability":{"entity_types":[],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":null,"required_evidence":[{"description":"Transaction monitoring logs","evidence_type":"DOCUMENT"}],"ambiguity_note":null,"self_confidence":0.95},{"section_id":"4.1","requirement_text":"Principal Officer must share and report information to the FIU.","source_quote":"shall be responsible for ... sharing and reporting information to the Financial Intelligence Unit (FIU)","modality":"MUST","obligation_type":"REPORTING","subject":"Principal Officer","action":"share and report information to the FIU","condition":null,"frequency_text":null,"deadline_text":null,"applicability":{"entity_types":[],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":null,"required_evidence":[{"description":"Copies of reports submitted to FIU","evidence_type":"DOCUMENT"}],"ambiguity_note":null,"self_confidence":0.95},{"section_id":"4.2","requirement_text":"Regulated Entity must communicate the Principal Officer''s name and contact details to the FIU within 30 days of appointment.","source_quote":"The name and contact details of the Principal Officer shall be communicated to the FIU within 30 days of the appointment.","modality":"MUST","obligation_type":"REPORTING","subject":"Regulated Entity","action":"communicate the name and contact details of the Principal Officer to the FIU","condition":null,"frequency_text":null,"deadline_text":"within 30 days of the appointment","applicability":{"entity_types":["scheduled commercial bank","small finance bank"],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":null,"required_evidence":[{"description":"Copy of communication sent to FIU","evidence_type":"DOCUMENT"},{"description":"Acknowledgement receipt from FIU","evidence_type":"DOCUMENT"}],"ambiguity_note":null,"self_confidence":0.98}]}', 'groq', 'openai/gpt-oss-120b', 1457, 2763, '2026-10-08 00:29:35.095624+00', 3, '2026-10-08 05:46:04.348417+00', NULL);
INSERT INTO public.llm_cache VALUES ('5ee5da30ec1041567a466df2c6995a1ad8d422f6ae682d459c2a28090c9d0893', 'obligation_verification', '{"results":[{"candidate_id":"0","entailed":true,"reason":"The source text explicitly requires every RE to have a KYC policy approved by its Board of Directors."},{"candidate_id":"1","entailed":true,"reason":"The source text states that the KYC policy shall be reviewed by the Board at least once a year."},{"candidate_id":"2","entailed":true,"reason":"The source text mandates that the RE shall nominate a Principal Officer."},{"candidate_id":"3","entailed":true,"reason":"The source text specifies that the Principal Officer shall be responsible for ensuring compliance."},{"candidate_id":"4","entailed":true,"reason":"The source text mandates that the name and contact details of the Principal Officer be communicated to the FIU within 30 days of appointment."}]}', 'gemini', 'gemini-3.5-flash-lite', 600, 257, '2026-10-08 00:29:47.408391+00', 3, '2026-10-08 05:46:04.368081+00', NULL);
INSERT INTO public.llm_cache VALUES ('1a104d8dc4e35cfbc2934a20ea5e58c70d441bea9e017cee3c0da01234f57afc', 'obligation_extraction', '{"obligations":[{"section_id":"5.1","requirement_text":"The RE shall undertake customer due diligence (CDD) at the time of commencement of an account-based relationship, by identifying the customer and verifying the identity using officially valid documents.","source_quote":"The RE shall undertake customer due diligence (CDD) at the time of commencement of an account-based relationship, by identifying the customer and verifying the identity using officially valid documents.","modality":"MUST","obligation_type":"CUSTOMER_DUE_DILIGENCE","subject":"RE","action":"Undertake customer due diligence (CDD) by identifying the customer and verifying the identity using officially valid documents","condition":"At the time of commencement of an account-based relationship","frequency_text":null,"deadline_text":null,"applicability":{"entity_types":[],"products":["account-based relationship"],"customer_segments":[],"thresholds":[]},"responsible_function":"Compliance / KYC","required_evidence":[{"description":"KYC records showing identification and verification using officially valid documents","evidence_type":"DOCUMENT"},{"description":"System logs or account opening records confirming CDD was performed at commencement","evidence_type":"SYSTEM_LOG"}],"ambiguity_note":null,"self_confidence":0.98},{"section_id":"5.2","requirement_text":"The RE shall not open an account where it is unable to apply appropriate CDD measures.","source_quote":"The RE shall not open an account where it is unable to apply appropriate CDD measures.","modality":"MUST_NOT","obligation_type":"CUSTOMER_DUE_DILIGENCE","subject":"RE","action":"Open an account","condition":"Where it is unable to apply appropriate CDD measures","frequency_text":null,"deadline_text":null,"applicability":{"entity_types":[],"products":["account"],"customer_segments":[],"thresholds":[]},"responsible_function":"Compliance / KYC","required_evidence":[{"description":"Account opening rejection logs or records showing accounts not opened due to inability to apply CDD","evidence_type":"SYSTEM_LOG"},{"description":"Policy or procedure document outlining criteria for refusing account opening when CDD cannot be applied","evidence_type":"DOCUMENT"}],"ambiguity_note":null,"self_confidence":0.98},{"section_id":"5.3","requirement_text":"Where the customer is a legal entity, the RE shall identify the beneficial owner holding more than 10 per cent of the ownership interest.","source_quote":"Where the customer is a legal entity, the RE shall identify the beneficial owner holding more than 10 per cent of the ownership interest.","modality":"MUST","obligation_type":"CUSTOMER_DUE_DILIGENCE","subject":"RE","action":"Identify the beneficial owner holding more than 10 per cent of the ownership interest","condition":"Where the customer is a legal entity","frequency_text":null,"deadline_text":null,"applicability":{"entity_types":["legal entity"],"products":[],"customer_segments":[],"thresholds":["more than 10 per cent of the ownership interest"]},"responsible_function":"Compliance / KYC","required_evidence":[{"description":"Beneficial ownership records for legal entity customers showing identification of owners with >10% interest","evidence_type":"DOCUMENT"},{"description":"Shareholding certificates or registry extracts confirming ownership percentages","evidence_type":"DOCUMENT"}],"ambiguity_note":null,"self_confidence":0.97},{"section_id":"6.1","requirement_text":"The RE shall categorise customers as low, medium or high risk based on the assessment of money laundering and terrorist financing risk.","source_quote":"The RE shall categorise customers as low, medium or high risk based on the assessment of money laundering and terrorist financing risk.","modality":"MUST","obligation_type":"RISK_ASSESSMENT","subject":"RE","action":"Categorise customers as low, medium or high risk","condition":"Based on the assessment of money laundering and terrorist financing risk","frequency_text":null,"deadline_text":null,"applicability":{"entity_types":[],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":"Compliance / Risk Management","required_evidence":[{"description":"Customer risk categorisation records showing low, medium, or high risk classification","evidence_type":"DOCUMENT"},{"description":"Risk assessment methodology or policy document outlining criteria for ML/TF risk categorisation","evidence_type":"DOCUMENT"}],"ambiguity_note":null,"self_confidence":0.98},{"section_id":"6.2","requirement_text":"The risk categorisation of customers shall be reviewed at least once in six months.","source_quote":"The risk categorisation of customers shall be reviewed at least once in six months.","modality":"MUST","obligation_type":"RISK_ASSESSMENT","subject":"RE","action":"Review the risk categorisation of customers","condition":null,"frequency_text":"at least once in six months","deadline_text":null,"applicability":{"entity_types":[],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":"Compliance / Risk Management","required_evidence":[{"description":"Records of periodic risk categorisation reviews with dates and outcomes","evidence_type":"DOCUMENT"},{"description":"System logs or audit trails showing risk reviews conducted at the required frequency","evidence_type":"SYSTEM_LOG"}],"ambiguity_note":null,"self_confidence":0.98},{"section_id":"7.1","requirement_text":"The RE shall carry out periodic updation of KYC at least once every two years for high risk customers.","source_quote":"The RE shall carry out periodic updation of KYC at least once every two years for high risk customers.","modality":"MUST","obligation_type":"CUSTOMER_DUE_DILIGENCE","subject":"RE","action":"Carry out periodic updation of KYC","condition":"For high risk customers","frequency_text":"at least once every two years","deadline_text":null,"applicability":{"entity_types":[],"products":[],"customer_segments":["high risk customers"],"thresholds":[]},"responsible_function":"Compliance / KYC","required_evidence":[{"description":"KYC updation records for high-risk customers showing dates of review and updated information","evidence_type":"DOCUMENT"},{"description":"System reports listing high-risk customers and their last KYC updation dates","evidence_type":"SYSTEM_LOG"}],"ambiguity_note":null,"self_confidence":0.98}]}', 'groq#2', 'qwen/qwen3.8-27b', 1401, 2006, '2026-10-08 00:29:57.433401+00', 3, '2026-10-08 05:46:04.846555+00', NULL);
INSERT INTO public.llm_cache VALUES ('d0e1fba3bd50b7c4261993d492ce503f9f9ce68f29f801308f89e0ab9731bdb1', 'applicability', '{"decisions":[{"obligation_id":"1a0add1c-e44f-428c-9370-a47fcf1fa07f","decision":"APPLICABLE","rationale":"The bank offers corporate accounts and retail deposits which constitute account-based relationships.","confidence":0.95},{"obligation_id":"176705ff-1dff-4bfe-b0d3-dfc18ebdc606","decision":"UNCERTAIN","rationale":"The bank profile does not specify whether it serves customers that are legal entities.","confidence":0.9}]}', 'gemini', 'gemini-3.5-flash-lite', 494, 189, '2026-10-08 05:46:09.093727+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('9184036fda2cdefabeb42cc880722077d20c57145506687c2e25bb48d17c3563', 'control_mapping', '{"mappings":[{"obligation_id":"3.1","judgements":[{"control_key":"C-KYC-01","relation":"FULL","coverage":1.0,"confidence":0.95,"control_quote":"The KYC and AML policy is approved by the Board of Directors","reason":"The control explicitly states the policy is approved by the Board of Directors, which directly satisfies the obligation to have a KYC policy approved by the Board."},{"control_key":"C-KYC-04","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"This control addresses beneficial owner identification during onboarding, not the approval of the KYC policy by the Board."},{"control_key":"C-KYC-13","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"This control describes an internal audit process for compliance testing, not the initial approval of the policy by the Board."},{"control_key":"C-KYC-03","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"This control describes the Customer Due Diligence (CDD) workflow at onboarding, not the governance approval of the KYC policy."}]},{"obligation_id":"3.2","judgements":[{"control_key":"C-KYC-01","relation":"FULL","coverage":1.0,"confidence":0.95,"control_quote":"placed before the Board for review every year","reason":"The control specifies that the policy is placed before the Board for review every year, which meets the requirement of at least once a year."},{"control_key":"C-KYC-13","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"This control involves Internal Audit testing compliance, not the Board''s review of the policy itself."},{"control_key":"C-KYC-12","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"This control concerns staff training, not the Board''s review of the KYC policy."},{"control_key":"C-KYC-06","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"This control tracks customer KYC updation, not the Board''s review of the policy document."}]},{"obligation_id":"4.1","judgements":[{"control_key":"C-KYC-02","relation":"FULL","coverage":1.0,"confidence":0.95,"control_quote":"The Board designates a Principal Officer for AML","reason":"The control explicitly states that the Board designates a Principal Officer, satisfying the obligation to nominate one."},{"control_key":"C-KYC-09","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"This control describes the workflow for filing Suspicious Transaction Reports, assuming the Principal Officer exists, but does not describe the nomination process."},{"control_key":"C-KYC-04","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"This control addresses beneficial owner identification, unrelated to the nomination of a Principal Officer."},{"control_key":"C-KYC-01","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"This control concerns the approval and review of the KYC policy, not the nomination of a Principal Officer."}]}]}', 'groq#2', 'qwen/qwen3.8-27b', 1604, 1143, '2026-10-08 05:46:35.364379+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('b849b01bed54d627705124d50505cb6d9470e0665239c7c3040b167b1f4ecaeb', 'control_mapping', '{"mappings":[{"obligation_id":"obligation_4.1","judgements":[{"control_key":"C-KYC-02","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"The control designates the Principal Officer but does not state that the Officer ensures overall compliance."},{"control_key":"C-KYC-09","relation":"PARTIAL","coverage":0.5,"confidence":0.9,"control_quote":"Alerts escalated as suspicious are reviewed by the Principal Officer and Suspicious Transaction Reports are filed with the FIU within seven working days of the conclusion","reason":"The control shows the Principal Officer participates in STR filing, a specific compliance task, but does not cover all compliance responsibilities."},{"control_key":"C-KYC-13","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"The control describes quarterly internal audits, not the Principal Officer’s duty to ensure compliance."},{"control_key":"C-KYC-01","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"The control concerns policy approval, not the Principal Officer’s compliance responsibility."}]},{"obligation_id":"obligation_4.2","judgements":[{"control_key":"C-KYC-02","relation":"FULL","coverage":1.0,"confidence":0.95,"control_quote":"Compliance communicates the name and contact details to the FIU within 30 days of any appointment","reason":"The control explicitly requires communication of the Principal Officer’s name and contact to the FIU within the 30‑day deadline."},{"control_key":"C-KYC-09","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"The control deals with STR filing, not communication of the Principal Officer’s details."},{"control_key":"C-KYC-10","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"The control concerns monthly CTR submission, unrelated to the required communication."},{"control_key":"C-IT-08","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"The control addresses cyber incident reporting, not the Principal Officer communication requirement."}]},{"obligation_id":"obligation_5.1","judgements":[{"control_key":"C-KYC-03","relation":"FULL","coverage":1.0,"confidence":0.95,"control_quote":"requires identity verification against officially valid documents before an account number is generated; accounts cannot be activated if CDD is incomplete","reason":"The control mandates CDD at onboarding with verification using official documents, matching the obligation."},{"control_key":"C-KYC-04","relation":"PARTIAL","coverage":0.5,"confidence":0.9,"control_quote":"identify beneficial owners holding more than 10% ownership and record them in the KYC Portal","reason":"The control covers identification of beneficial owners for legal entities, a subset of CDD, but does not address all customers or verification of identity."},{"control_key":"C-KYC-01","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"The control relates to policy approval and review, not to performing CDD at account opening."},{"control_key":"C-KYC-05","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"The control describes periodic risk categorisation review, not the initial CDD requirement."}]}]}', 'groq', 'openai/gpt-oss-120b', 1635, 2414, '2026-10-08 05:46:58.134116+00', 0, NULL, NULL);
