INSERT INTO public.llm_cache VALUES ('28177d399e9ecbaf117391b437a614aca338a7a25ad032dc28c74dd22c0b8d22', 'evidence_assessment', '{"verdicts":[{"criterion_id":"K1","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt only provides a completion percentage and does not show attendance records for all staff.","confidence":0.9},{"criterion_id":"K2","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No training materials or presentation content are presented in the excerpt.","confidence":0.9},{"criterion_id":"K3","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"Board meeting minutes are not included in the provided evidence.","confidence":0.9},{"criterion_id":"K4","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt does not contain an updated KYC policy.","confidence":0.9},{"criterion_id":"K5","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No records of high‑risk customer KYC updates are shown.","confidence":0.9},{"criterion_id":"K6","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"System reports listing high‑risk customers and their last KYC dates are absent.","confidence":0.9},{"criterion_id":"K7","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt provides no evidence of updated KYC records for medium‑risk customers.","confidence":0.9},{"criterion_id":"K8","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No audit log showing dates of each updation is included.","confidence":0.9}]}', 'groq', 'openai/gpt-oss-120b', 802, 632, '2026-10-08 05:51:02.576585+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('fe2ce9e0fa6bc942dcff3c659746e245acb3e63cbf75384f3064c20861f5ffac', 'evidence_assessment', '{"verdicts":[{"criterion_id":"K1","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No evidence of training attendance or completion reports provided.","confidence":0.8},{"criterion_id":"K2","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No training materials or presentation content were presented.","confidence":0.8},{"criterion_id":"K3","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No appointment letter or Board resolution for the DPO was found.","confidence":0.8},{"criterion_id":"K4","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"Employment documentation for the DPO''s location is absent.","confidence":0.8},{"criterion_id":"K5","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The approved KYC policy document itself was not supplied.","confidence":0.8},{"criterion_id":"K6","verdict":"MET","evidence_id":"15960caf-43b4-475b-a069-d42fb2b4c4b7","quote":"Resolved that the revised Know Your Customer and Anti-Money Laundering Policy, as placed before the Board, is hereby approved.","rationale":"Board minutes explicitly record approval of the policy.","confidence":0.95},{"criterion_id":"K7","verdict":"INSUFFICIENT","evidence_id":"15960caf-43b4-475b-a069-d42fb2b4c4b7","quote":"The Board noted that the policy shall be reviewed annually.","rationale":"Minutes indicate intent to review annually but do not show an actual review took place.","confidence":0.8},{"criterion_id":"K8","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No updated KYC policy reflecting a review was provided.","confidence":0.8}]}', 'groq', 'openai/gpt-oss-120b', 816, 844, '2026-10-08 05:51:04.945371+00', 0, NULL, NULL);
