INSERT INTO public.llm_cache VALUES ('db2076137e4775d4e2fbad1dedefc8d0a8998bfebd17da1a2f4746ac34669c52', 'impact_planning', '{"steps":["diff_versions","extract_obligations","carry_forward","assess_applicability","map_controls","assess_evidence","score_controls","identify_gaps","score_risk","recommend_remediation","cross_regulation","impact_report"],"rationale":"Since this is a new version with an existing previous version, we begin by diffing the versions and extracting obligations, carrying them forward to maintain traceability. We then assess applicability, map controls, assess evidence, and score control effectiveness. Next, we identify gaps, score the associated risks, recommend remediation, perform cross-regulation analysis, and finally produce the comprehensive impact report."}', 'gemini', 'gemini-3.5-flash-lite', 441, 181, '2026-10-08 06:30:59.148007+00', 0, NULL, NULL);
