INSERT INTO public.llm_cache VALUES ('b8f94021cd4cf91be14f11d5268b739895c55e482f3b1bfba9e4e273fa1a8bd3', 'evidence_assessment', '{"verdicts":[{"criterion_id":"K1","verdict":"MET","evidence_id":"E1","quote":"Log records include user identifiers and source IP addresses.","rationale":"Excerpt shows logs of privileged sessions captured by PAM.","confidence":0.85},{"criterion_id":"K2","verdict":"MET","evidence_id":"E1","quote":"Log source PAM-01 retention policy: 180 days hot storage.","rationale":"Explicit retention policy of 180 days is documented.","confidence":0.95},{"criterion_id":"K3","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No information on log storage or retrieval capabilities is provided.","confidence":0.7},{"criterion_id":"K4","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"Patch management logs are not mentioned in the excerpt.","confidence":0.7},{"criterion_id":"K5","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"System update reports are absent from the evidence.","confidence":0.7},{"criterion_id":"K6","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"Backup logs are not referenced in the provided document.","confidence":0.7},{"criterion_id":"K7","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No backup schedules are described in the excerpt.","confidence":0.7},{"criterion_id":"K8","verdict":"NOT_MET","evidence_id":"E1","quote":"Log source PAM-01 retention policy: 180 days hot storage.","rationale":"Retention period exceeds the required automatic deletion after 90 days.","confidence":0.9}]}', 'groq', 'openai/gpt-oss-120b', 753, 1036, '2026-10-08 06:17:28.810595+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('0c0062f84d758981662939b13cfac3467814ddf31189a98da34a866f49c634a2', 'remediation', '{"plans":[{"finding_id":"F1","root_cause":"The bank''s data retention policy does not explicitly reconcile the 3-year erasure deadline from the Data Protection obligation with potential longer retention requirements under other laws (e.g., AML or tax laws), creating a compliance conflict where the system may either erase data too early or retain it too long without a documented legal basis.","actions":[{"kind":"POLICY_UPDATE","description":"Update the Data Retention Policy to include a specific clause that prioritizes the 3-year erasure deadline unless a specific legal hold is documented, and define the process for legal review of retention exceptions."},{"kind":"PROCESS_CHANGE","description":"Implement a legal hold workflow in the account closure process where Legal/Compliance must approve any retention beyond 3 years with a cited legal basis before the data is exempted from erasure."},{"kind":"TECHNOLOGY_CHANGE","description":"Configure the core banking system''s data lifecycle management module to automatically flag accounts closed more than 3 years ago for erasure review, unless a legal hold flag is present."},{"kind":"TESTING","description":"Conduct a sample test of 50 closed accounts to verify that data is erased within 3 years or that a valid legal hold is documented for any retained data."}],"suggested_owner":"Data Protection Officer / Head of Operations","target_days":90,"dependencies":["Legal Department","Core Banking System Vendor","IT Operations"],"expected_evidence":"Updated Data Retention Policy, Legal Hold Approval Logs, and System Configuration Screenshots showing the 3-year erasure trigger.","verification_method":"Compliance will review the updated policy, inspect legal hold records for a sample of closed accounts, and verify system logs for erasure actions within the 3-year window.","touches_production":true},{"finding_id":"F2","root_cause":"IT and Information Security have not aligned system and application log retention settings with the 90-day data protection limit, likely due to conflicting operational requirements for troubleshooting or security forensics that are not explicitly reconciled with data minimization principles.","actions":[{"kind":"POLICY_UPDATE","description":"Revise the IT Log Management Policy to mandate a maximum retention period of 90 days for all system and application logs containing personal data, with exceptions only for active security incidents."},{"kind":"TECHNOLOGY_CHANGE","description":"Update log management tools (e.g., SIEM, ELK stack) to automatically purge or anonymize logs containing personal data after 90 days, and configure alerts for any retention exceeding this limit."},{"kind":"PROCESS_CHANGE","description":"Establish a quarterly review process for IT to audit log retention settings across all applications and ensure compliance with the 90-day limit."},{"kind":"TESTING","description":"Perform a technical audit of log storage systems to verify that logs older than 90 days are automatically deleted or anonymized."}],"suggested_owner":"Chief Information Security Officer (CISO) / IT Director","target_days":60,"dependencies":["IT Operations","Security Operations Center (SOC)","Application Owners"],"expected_evidence":"Updated IT Log Management Policy, Configuration Files showing 90-day retention settings, and Audit Reports confirming automatic purging.","verification_method":"Compliance will inspect log management configurations, review audit logs for automatic deletion events, and verify that no logs containing personal data exceed 90 days retention.","touches_production":true}]}', 'groq#2', 'qwen/qwen3.8-27b', 935, 914, '2026-10-08 06:17:32.241973+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('227083fcea421fad2be882803bf2ff2199d2f69f78b87016c02f2340e59d8989', 'remediation', '{"plans":[{"finding_id":"F1","root_cause":"No formal record‑retention policy or supporting process has been defined for transaction records, resulting in a regulatory gap.","actions":[{"kind":"POLICY_UPDATE","description":"Draft and approve a Record Retention Policy (RRP‑01) that mandates retaining all transaction records for a minimum of five years from the transaction date."},{"kind":"PROCESS_CHANGE","description":"Define a Transaction Record Archiving Process (TRAP‑01) that moves completed transaction files to the archival store within 30 days of settlement."},{"kind":"TECHNOLOGY_CHANGE","description":"Configure the Enterprise Data Archive system to enforce a five‑year retention period for the Transaction Archive folder, with automatic deletion thereafter."},{"kind":"EVIDENCE_COLLECTION","description":"Collect the approved RRP‑01 policy, TRAP‑01 SOP, and archive system configuration screenshots as compliance evidence."},{"kind":"APPROVAL","description":"Obtain sign‑off from the Chief Compliance Officer and the Head of IT on the new policy, process, and system settings."}],"suggested_owner":"Chief Compliance Officer (CCO)","target_days":60,"dependencies":["IT Records Management Team","Legal Department","Data Governance Office"],"expected_evidence":"Signed Record Retention Policy (RRP‑01), Transaction Record Archiving SOP (TRAP‑01), archive system retention configuration logs, and evidence of retention audit for a sample of >5‑year‑old transaction records.","verification_method":"Internal audit will sample transaction records older than five years to confirm they remain stored per the configured retention schedule and that deletion occurs only after the five‑year period.","touches_production":true},{"finding_id":"F2","root_cause":"Absence of a documented retention framework for customer identification records after relationship termination, leading to non‑compliance with the five‑year preservation requirement.","actions":[{"kind":"POLICY_UPDATE","description":"Create and ratify a Customer Identification Record Retention Policy (CIRP‑01) requiring preservation of KYC files for five years after account closure."},{"kind":"PROCESS_CHANGE","description":"Establish a Customer Record Closure Process (CRCP‑01) that flags closed accounts and triggers archival of KYC documents into the Secure Retention Vault."},{"kind":"TECHNOLOGY_CHANGE","description":"Update the Secure Retention Vault configuration to apply a five‑year retention rule to all KYC records tagged by CRCP‑01."},{"kind":"EVIDENCE_COLLECTION","description":"Gather the approved CIRP‑01 policy, CRCP‑01 workflow documentation, and vault retention rule screenshots as proof of compliance."},{"kind":"APPROVAL","description":"Secure formal approval from the Head of Compliance and the Data Security Manager for the policy, process, and vault settings."}],"suggested_owner":"Head of Compliance (Compliance Manager)","target_days":60,"dependencies":["IT Security Team","Legal Department","Data Management Office"],"expected_evidence":"Signed Customer Identification Record Retention Policy (CIRP‑01), Customer Record Closure SOP (CRCP‑01), Secure Vault retention rule logs, and a retention verification report for a sample of closed‑account KYC files older than five years.","verification_method":"Quarterly compliance audit will verify that KYC records for closed accounts are retained for at least five years and that no premature deletions have occurred, using vault logs and sample record checks.","touches_production":true}]}', 'groq', 'openai/gpt-oss-120b', 989, 997, '2026-10-08 06:18:23.458579+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('7b8056a9340437f60a13a9e680a19837dcd7aaa57b23186e5b6b8051a7e16231', 'remediation', '{"plans":[{"finding_id":"F1","root_cause":"No formal record‑retention control exists and the logging infrastructure is not configured to enforce the 180‑day retention required by regulation 3.3, creating a conflict with other regulatory requirements.","actions":[{"kind":"POLICY_UPDATE","description":"Draft, review and approve a Record Retention Policy that explicitly mandates a minimum of 180 days log retention for all system logs per regulation 3.3."},{"kind":"CONTROL_CHANGE","description":"Create a new control C-REC-01 “Log Retention – 180 days” in the control register and assign ownership to IT Operations."},{"kind":"TECHNOLOGY_CHANGE","description":"Configure the central logging platform (e.g., Splunk/ELK) to automatically archive logs for 180 days and purge any log data older than 180 days."},{"kind":"EVIDENCE_COLLECTION","description":"Generate a retention‑configuration report and capture a sample of archived logs showing timestamps that span at least the last 180 days."},{"kind":"TESTING","description":"Perform a quarterly audit of the logging system to verify that logs older than 180 days are deleted and that retention settings remain compliant."},{"kind":"APPROVAL","description":"Obtain sign‑off from the CISO and Legal on the updated policy, new control, and logging configuration."}],"suggested_owner":"Information Security Manager (IT Department)","target_days":45,"dependencies":["Logging Platform Team","Legal Department","Compliance Office"],"expected_evidence":"Signed Record Retention Policy, control register entry for C-REC-01, logging platform retention configuration screenshot, quarterly retention audit report.","verification_method":"Internal audit will review the retention configuration, examine deletion logs, and confirm that archived logs cover the required 180‑day window.","touches_production":true},{"finding_id":"F2","root_cause":"The V‑CIP interaction recording requirement is not captured in any policy or control and the V‑CIP gateway is not configured to record sessions, leading to a regulatory conflict.","actions":[{"kind":"POLICY_UPDATE","description":"Update the V‑CIP Interaction Recording Policy to require capture and retention of all V‑CIP sessions for at least 180 days."},{"kind":"CONTROL_CHANGE","description":"Add control C-REC-02 “V‑CIP Interaction Recording” to the control register, linking it to the Record Retention Policy."},{"kind":"TECHNOLOGY_CHANGE","description":"Enable session recording on the V‑CIP gateway and configure storage to retain recordings for a minimum of 180 days."},{"kind":"EVIDENCE_COLLECTION","description":"Export the V‑CIP gateway configuration and provide sample recorded session files that demonstrate retention over the required period."},{"kind":"TESTING","description":"Conduct a quarterly test to verify that every V‑CIP session generates a recording and that recordings are retained according to the 180‑day rule."},{"kind":"APPROVAL","description":"Secure sign‑off from the Head of IT Security and Business Continuity on the policy amendment, new control, and gateway configuration."}],"suggested_owner":"Head of IT Security (IT Department)","target_days":60,"dependencies":["V‑CIP System Team","Legal Department","Compliance Office"],"expected_evidence":"Revised V‑CIP Interaction Recording Policy, control register entry for C-REC-02, V‑CIP gateway configuration screenshot, sample recordings retained for 180 days, quarterly recording compliance report.","verification_method":"Compliance audit will review the V‑CIP configuration, sample recordings, and retention logs to confirm continuous recording and proper retention for the mandated period.","touches_production":true}]}', 'groq', 'openai/gpt-oss-120b', 954, 1562, '2026-10-08 06:18:27.773044+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('98deb7c86aed7a0c5e2d89213b63915014ccac5a2315833167b633f7594148e5', 'control_mapping', '{"mappings":[{"obligation_id":"O1","judgements":[{"control_key":"C-KYC-02","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"The control concerns AML Principal Officer designation and FIU notification, not the reporting line of the CISO."},{"control_key":"C-IT-10","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"The control describes an annual IS audit reporting to the Audit Committee, which does not establish the CISO''s direct reporting line to the Executive Director."},{"control_key":"C-IT-08","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"The control addresses cyber incident reporting to the regulator, not the organizational reporting structure of the CISO."},{"control_key":"C-KYC-09","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"The control describes the STR filing workflow, which is unrelated to the CISO''s reporting line."}]},{"obligation_id":"O2","judgements":[{"control_key":"C-IT-01","relation":"FULL","coverage":1.0,"confidence":0.98,"control_quote":"Privileged users of critical systems authenticate with multi-factor authentication enforced by the identity provider.","reason":"The control explicitly enforces MFA for privileged users of critical systems, matching the obligation''s scope and action exactly."},{"control_key":"C-IT-02","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"The control addresses access rights review, not the implementation of multi-factor authentication."},{"control_key":"C-IT-03","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"The control addresses session logging and retention, not the implementation of multi-factor authentication."},{"control_key":"C-IT-04","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"The control addresses patch management, not the implementation of multi-factor authentication."}]},{"obligation_id":"O3","judgements":[{"control_key":"C-IT-02","relation":"FULL","coverage":1.0,"confidence":0.98,"control_quote":"Application owners review user access rights to critical systems every quarter","reason":"The control specifies a quarterly review of user access rights to critical systems, which matches the required frequency and scope of the obligation."},{"control_key":"C-IT-07","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"The control addresses data backup and restore testing, not the review of user access rights."},{"control_key":"C-IT-01","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"The control addresses MFA implementation, not the periodic review of user access rights."},{"control_key":"C-IT-06","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"The control addresses vulnerability assessment and penetration testing, not the review of user access rights."}]}]}', 'groq#2', 'qwen/qwen3.8-27b', 1388, 1111, '2026-10-08 06:06:17.883066+00', 1, '2026-10-08 06:22:58.301961+00', NULL);
INSERT INTO public.llm_cache VALUES ('1171aa1b4419d1af56151c507a8af66b5968175b80af3bb84444d4ab9a3a04e4', 'control_mapping', '{"mappings":[{"obligation_id":"O1","judgements":[{"control_key":"C-IT-03","relation":"FULL","coverage":0.96,"confidence":0.99,"control_quote":"All privileged sessions are recorded by the PAM solution","reason":"The control explicitly records all privileged sessions, satisfying the obligation to log privileged access sessions."},{"control_key":"C-IT-02","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control describes quarterly access reviews, which does not address logging of privileged sessions."},{"control_key":"C-IT-01","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control describes MFA for privileged users, unrelated to session logging."},{"control_key":"C-KYC-07","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control records video KYC sessions, not privileged access sessions."}]},{"obligation_id":"O2","judgements":[{"control_key":"C-IT-03","relation":"FULL","coverage":0.97,"confidence":0.99,"control_quote":"logs are retained for 180 days in the SIEM","reason":"The control states logs are retained for 180 days, meeting the minimum 180‑day retention requirement."},{"control_key":"C-KYC-08","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control concerns transaction and customer records retention, not privileged session logs."},{"control_key":"C-IT-02","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control describes quarterly access reviews, unrelated to log retention."},{"control_key":"C-IT-01","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control describes MFA, which does not address log retention."}]},{"obligation_id":"O3","judgements":[{"control_key":"C-IT-04","relation":"PARTIAL","coverage":0.55,"confidence":0.95,"control_quote":"Critical security patches are deployed to critical systems within 30 days of release","reason":"The control covers patch deployment to critical systems but the deadline is 30 days, longer than the required 14 days, so it only partially satisfies the obligation."},{"control_key":"C-IT-01","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control describes MFA for privileged users, which does not relate to patch application."},{"control_key":"C-IT-02","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control describes quarterly user access reviews, unrelated to patch management."},{"control_key":"C-IT-03","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control concerns privileged session logging, not patch application."}]}]}', 'groq', 'openai/gpt-oss-120b', 1424, 2217, '2026-10-08 06:07:15.288221+00', 1, '2026-10-08 06:22:58.328608+00', NULL);
INSERT INTO public.llm_cache VALUES ('82f9c2b8c20451dada160770aa8041bd6e575cd28734cd73cd8ebc364f25bc6f', 'control_mapping', '{"mappings":[{"obligation_id":"O1","judgements":[{"control_key":"C-KYC-02","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"The control addresses the designation of a Principal Officer and notification to the FIU, not the submission of a root cause analysis report to the Board."},{"control_key":"C-KYC-09","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"The control concerns the filing of Suspicious Transaction Reports with the FIU, not the submission of a root cause analysis report to the Board."},{"control_key":"C-KYC-04","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"The control relates to beneficial owner identification during onboarding, which is unrelated to root cause analysis reporting."},{"control_key":"C-IT-05","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"The control describes a disaster recovery drill and reporting to the IT Strategy Committee, not a root cause analysis report to the Board."}]},{"obligation_id":"O2","judgements":[{"control_key":"C-IT-10","relation":"FULL","coverage":1.0,"confidence":0.98,"control_quote":"An independent auditor conducts an information systems audit every year","reason":"The control specifies an independent auditor conducting an IS audit every year, which matches the obligation''s requirement for an independent IS audit at least once a year."},{"control_key":"C-IT-06","relation":"PARTIAL","coverage":0.5,"confidence":0.85,"control_quote":"An external firm performs vulnerability assessment and penetration testing of all critical systems once a year","reason":"While performed annually by an external firm, vulnerability assessment and penetration testing are specific technical tests and do not constitute a comprehensive Information Systems audit as required."},{"control_