INSERT INTO public.llm_cache VALUES ('709eb6dfbc044148da2986d86da46e2dd4e05c3bfc15479fcc097088e8306f58', 'control_mapping', '{"mappings":[{"obligation_id":"O1","judgements":[{"control_key":"C-KYC-03","relation":"FULL","coverage":0.96,"confidence":0.99,"control_quote":"CDD at onboarding. The core banking onboarding workflow requires identity verification against officially valid documents before an account number is generated; accounts cannot be activated if CDD is incomplete.","reason":"The control performs identity verification using officially valid documents at onboarding, matching the obligation''s requirement to undertake CDD at commencement of an account relationship."},{"control_key":"C-KYC-04","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control only addresses beneficial-owner identification for legal entities and does not cover general customer due diligence at onboarding."},{"control_key":"C-KYC-01","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control concerns policy approval and annual review, not the execution of CDD at account opening."},{"control_key":"C-KYC-05","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"The control reviews risk categorisation semi-annually and does not perform initial CDD."}]},{"obligation_id":"O2","judgements":[{"control_key":"C-KYC-03","relation":"FULL","coverage":0.96,"confidence":0.99,"control_quote":"CDD at onboarding. The core banking onboarding workflow requires identity verification against officially valid documents before an account number is generated; accounts cannot be activated if CDD is incomplete.","reason":"The control prevents account activation when CDD is incomplete, ensuring the bank does not open accounts without appropriate CDD."},{"control_key":"C-IT-01","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"MFA for privileged users does not relate to the ability to