INSERT INTO public.llm_cache VALUES ('3ed786cb8acc58f1a86cc14f038a108fac6447840e2582a4a0c690567fe40e51', 'evidence_assessment', '{"verdicts":[{"criterion_id":"K1","verdict":"MET","evidence_id":"E1","quote":"Log records include user identifiers and source IP addresses.","rationale":"The excerpt confirms that log records contain specific details (user identifiers, source IPs) associated with the PAM log source, demonstrating the existence of system logs for privileged access.","confidence":0.9},{"criterion_id":"K2","verdict":"MET","evidence_id":"E1","quote":"Log source PAM-01 retention policy: 180 days hot storage.","rationale":"The excerpt explicitly states the retention policy for the PAM log source is 180 days, satisfying the criterion for a defined log retention policy.","confidence":0.95},{"criterion_id":"K3","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt mentions storage duration but does not provide evidence of retrieval capabilities or specific storage mechanisms beyond the policy statement.","confidence":0.8},{"criterion_id":"K4","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt defines a 180-day retention policy but does not demonstrate configuration for automatic truncation or deletion of logs older than 90 days.","confidence":0.9},{"criterion_id":"K5","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"There is no mention of audit records or logs related to log purging jobs in the provided excerpt.","confidence":0.95},{"criterion_id":"K6","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt describes a retention policy but does not provide evidence of an actual transaction record archive covering the period.","confidence":0.9}]}', 'groq#2', 'qwen/qwen3.8-27b', 691, 561, '2026-10-08 06:23:15.28181+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('1f90a2e9c25e77eff96a21eb3c5e6ffa8772e20fdf645c48e0d22075b46a6fad', 'remediation', '{"plans":[{"finding_id":"F1","root_cause":"The bank has no documented control or standard operating procedure that requires a root cause analysis for every critical incident, resulting in a missing control gap for the incident management obligation.","actions":[{"kind":"POLICY_UPDATE","description":"Update the Incident Management Policy to mandate a root cause analysis for all critical incidents within 5 business days of incident closure."},{"kind":"CONTROL_CHANGE","description":"Create control C-IM-01 \"Conduct root cause analysis for every critical incident\" and assign ownership to the Incident Response Team."},{"kind":"PROCESS_CHANGE","description":"Develop a detailed SOP for performing root cause analysis, including data collection, analysis steps, documentation format, and escalation path."},{"kind":"EVIDENCE_COLLECTION","description":"Add a required field in the incident tracking system to attach the completed root cause analysis report for each critical incident."},{"kind":"APPROVAL","description":"Obtain formal sign‑off from the Chief Risk Officer and Compliance on the new policy amendment, control C-IM-01, and SOP."}],"suggested_owner":"Incident Response Manager","target_days":45,"dependencies":["Risk Management","Compliance","IT Service Management (ITSM) platform team"],"expected_evidence":"Approved Incident Management Policy amendment, control register entry C-IM-01, SOP document, sample incident record with attached root cause analysis report in the tracking system.","verification_method":"Internal audit will sample critical incidents from the last quarter to verify that a root cause analysis was performed, documented, and attached per the new control.","touches_production":false},{"finding_id":"F2","root_cause":"There is no existing control or workflow to ensure the bank notifies the Authority of a personal data breach within the statutory 72‑hour window, leaving the reporting obligation uncovered.","actions":[{"kind":"POLICY_UPDATE","description":"Amend the Data Protection Policy to include a mandatory breach notification to the Authority within 72 hours of awareness."},{"kind":"CONTROL_CHANGE","description":"Create control C-PR-01 \"Notify Authority of personal data breach within 72 hours\" with the Data Protection Officer as owner."},{"kind":"PROCESS_CHANGE","description":"Design a breach response workflow that triggers a notification task and deadline when a breach is logged."},{"kind":"TECHNOLOGY_CHANGE","description":"Configure the incident management system to automatically generate the notification task, enforce the 72‑hour deadline, and log timestamps."},{"kind":"EVIDENCE_COLLECTION","description":"Produce breach notification logs showing the date/time of breach awareness and the date/time of Authority notification."},{"kind":"APPROVAL","description":"Secure sign‑off from the Data Protection Officer and Legal on the policy amendment, control C-PR-01, and system workflow configuration."}],"suggested_owner":"Data Protection Officer","target_days":40,"dependencies":["Legal","IT Security","Incident Management System team"],"expected_evidence":"Updated Data Protection Policy, control register entry C-PR-01, screenshot of configured workflow with deadline enforcement, and breach notification logs demonstrating compliance with the 72‑hour requirement.","verification_method":"Compliance will conduct a simulated breach drill to verify the workflow creates a notification task and that the Authority is notified within 72 hours, reviewing system logs for timestamps.","touches_production":true}]}', 'groq', 'openai/gpt-oss-120b', 975, 1458, '2026-10-08 06:24:07.408851+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('49048e4c188354130e5257a9c8f4066ba6f95ef17b9d3ef18380836846965227', 'remediation', '{"plans":[{"finding_id":"F1","root_cause":"The organization has no documented governance control or policy that mandates the appointment of a Chief Information Security Officer, resulting in a missing control for the regulatory obligation.","actions":[{"kind":"POLICY_UPDATE","description":"Draft and approve a Governance Policy amendment that defines the requirement to appoint a Chief Information Security Officer (CISO) and outlines reporting lines."},{"kind":"CONTROL_CHANGE","description":"Create control C-GOV-01 in the Control Register: \"CISO Appointment – The RE shall appoint a qualified CISO and maintain an up‑to‑date appointment record.\""},{"kind":"APPROVAL","description":"Obtain formal sign‑off from the Board and the Chief Risk Officer on the new policy amendment and control C‑GOV‑01."},{"kind":"PROCESS_CHANGE","description":"Update the annual governance review process to include verification of CISO appointment status and qualifications."},{"kind":"EVIDENCE_COLLECTION","description":"Collect the CISO appointment letter, updated policy document, and control register entry as evidence."},{"kind":"TESTING","description":"Internal audit to perform a compliance test during the next audit cycle to confirm the control is operating and evidence is retained."}],"suggested_owner":"Chief Risk Officer (CRO) / Governance & Compliance Function","target_days":45,"dependencies":["Legal Department","Human Resources","Board Secretariat"],"expected_evidence":"Signed policy amendment, control register entry C‑GOV‑01, CISO appointment letter, and audit test results.","verification_method":"Internal audit review of the control register and supporting documents, with a pass/fail assessment against the regulatory requirement.","touches_production":false},{"finding_id":"F2","root_cause":"There is no documented governance control or committee charter establishing an IT Strategy Committee of the Board, leaving the regulatory requirement unaddressed.","actions":[{"kind":"POLICY_UPDATE","description":"Develop a Board Charter amendment that creates an IT Strategy Committee, defines its composition, responsibilities, and meeting frequency."},{"kind":"CONTROL_CHANGE","description":"Add control C-GOV-02 to the Control Register: \"IT Strategy Committee – The Board shall constitute an IT Strategy Committee as defined in the Board Charter.\""},{"kind":"APPROVAL","description":"Secure Board approval of the charter amendment and formal adoption of control C‑GOV‑02."},{"kind":"PROCESS_CHANGE","description":"Integrate the IT Strategy Committee meeting schedule into the Board’s annual calendar and governance workflow."},{"kind":"EVIDENCE_COLLECTION","description":"Gather the updated Board Charter, minutes of the first IT Strategy Committee meeting, and control register entry as evidence."},{"kind":"TESTING","description":"Conduct a compliance test during the next Board governance review to verify the committee exists, meets regularly, and minutes are recorded."}],"suggested_owner":"Board Governance Office / Corporate Secretary","target_days":60,"dependencies":["Legal Department","Corporate Secretary","Board Members"],"expected_evidence":"Amended Board Charter, control register entry C‑GOV‑02, minutes of the inaugural IT Strategy Committee meeting, and test report from governance review.","verification_method":"Board governance audit to confirm the committee’s existence, charter compliance, and documented meeting evidence, with a compliance sign‑off.","touches_production":false}]}', 'groq', 'openai/gpt-oss-120b', 938, 945, '2026-10-08 06:24:10.200268+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('022faeeef5ddf72c5994b11db028b0a2cc0feb5fbe4cfb2642ba19e4c2233e29', 'remediation', '{"plans":[{"finding_id":"F1","root_cause":"The bank''s control framework lacks a specific governance control to ensure that the required report is submitted to the Board within the mandated 30-day deadline, resulting in 0% coverage for this obligation.","actions":[{"kind":"CONTROL_CHANGE","description":"Define and implement a new governance control (e.g., C-GOV-01) that mandates the preparation and submission of the specific report to the Board within 30 days of the reporting period end."},{"kind":"PROCESS_CHANGE","description":"Update the Board reporting calendar and internal reporting procedures to include a hard deadline of 30 days for this specific report, with automated reminders to the responsible function."},{"kind":"POLICY_UPDATE","description":"Amend the Corporate Governance Policy to explicitly state the 30-day submission requirement for this report and assign accountability to the Chief Compliance Officer or equivalent senior officer."},{"kind":"TESTING","description":"Perform a retrospective review of the last three reporting cycles to verify if the 30-day deadline was met and document any delays as baseline evidence."},{"kind":"APPROVAL","description":"Obtain formal approval from the Board Risk Committee for the new control definition and updated reporting timeline."}],"suggested_owner":"Chief Compliance Officer","target_days":45,"dependencies":["Board Secretariat","Internal Audit","Legal Department"],"expected_evidence":"Updated Corporate Governance Policy, new control definition in the GRC system, and Board minutes confirming the report submission within 30 days for the next cycle.","verification_method":"Compliance will re-test by reviewing the timestamp of the report submission in the Board portal against the reporting period end date to confirm adherence to the 30-day limit.","touches_production":false},{"finding_id":"F2","root_cause":"The bank has not appointed a Data Protection Officer (DPO) based in India as required by the Data Protection Act, and no control exists to monitor or enforce this statutory appointment.","actions":[{"kind":"PROCESS_CHANGE","description":"Initiate the recruitment or internal appointment process for a Data Protection Officer who is physically based in India, ensuring the candidate meets the statutory qualifications."},{"kind":"POLICY_UPDATE","description":"Update the Data Protection Policy to formally designate the appointed individual as the DPO, outlining their responsibilities, independence, and reporting line to the Board/Senior Management."},{"kind":"CONTROL_CHANGE","description":"Implement a governance control (e.g., C-DPO-01) that requires annual verification of the DPO''s appointment status, location, and independence."},{"kind":"EVIDENCE_COLLECTION","description":"Collect and archive the DPO''s appointment letter, proof of residence in India, and conflict of interest declaration."},{"kind":"APPROVAL","description":"Secure formal approval from the Board or Senior Management for the DPO appointment and the updated Data Protection Policy."}],"suggested_owner":"Chief Information Security Officer (CISO) or Head of Data Privacy","target_days":60,"dependencies":["Human Resources","Legal Department","Board / Senior Management"],"expected_evidence":"Signed DPO appointment letter, proof of India-based residence, updated Data Protection Policy, and Board resolution approving the appointment.","verification_method":"Compliance will verify the DPO''s appointment by reviewing HR records, the appointment letter, and confirming the DPO''s physical location in India via site visit or video verification.","touches_production":false}]}', 'groq#2', 'qwen/qwen3.8-27b', 877, 940, '2026-10-08 06:24:12.9082+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('513e269d24aba77b3683ee5a841771399e1ee4c10fd1e1c90e55fab9cac80033', 'remediation', '{"plans":[{"finding_id":"F1","root_cause":"The existing control only records video KYC sessions but does not enforce or capture evidence that the V‑CIP verification steps are completed, resulting in partial coverage of the onboarding obligation.","actions":[{"kind":"POLICY_UPDATE","description":"Update the V‑CIP onboarding policy to require a completed identity‑verification checklist and storage of the verification outcome alongside the video recording."},{"kind":"CONTROL_CHANGE","description":"Amend control C‑KYC‑07 to mandate capture of a verification‑result flag and audit‑log entry in the V‑CIP Platform for each session."},{"kind":"TECHNOLOGY_CHANGE","description":"Enhance the V‑CIP Platform to automatically validate that the verification checklist is completed before allowing a session to be marked complete."},{"kind":"EVIDENCE_COLLECTION","description":"Collect completed V‑CIP checklists and corresponding video recordings for a 30‑day pilot period to demonstrate compliance."},{"kind":"TESTING","description":"Sample 50 new onboarding cases and verify that the verification checklist, flag, and video recording are all present and approved."},{"kind":"APPROVAL","description":"Obtain sign‑off from the Head of Digital Banking and AML Compliance on the updated policy, control wording, and pilot evidence."}],"suggested_owner":"Head - Digital Banking","target_days":45,"dependencies":["V‑CIP Platform team","IT Security","Compliance"],"expected_evidence":"Revised V‑CIP policy document, updated C‑KYC‑07 control text, system configuration screenshot showing verification flag enforcement, pilot evidence package of checklists and videos, test sample report, approval sign‑off records.","verification_method":"Internal audit will review a random sample of onboarding records quarterly to confirm the verification checklist, flag, and video are present and that the control settings remain enforced.","touches_production":true},{"finding_id":"F2","root_cause":"The archive control retains customer data for five years, which exceeds the legal requirement to erase personal data within three years after account closure, creating a mismatch between policy and system retention settings.","actions":[{"kind":"POLICY_UPDATE","description":"Revise the Data Retention Policy to state that personal data must be erased no later than three years after account closure, overriding the previous five‑year rule."},{"kind":"CONTROL_CHANGE","description":"Update control C‑KYC‑08 description to reflect the three‑year deletion requirement and reference the new policy."},{"kind":"TECHNOLOGY_CHANGE","description":"Configure the Archive System to automatically delete customer data three years post‑closure, with an exception workflow for legal holds."},{"kind":"EVIDENCE_COLLECTION","description":"Generate deletion logs for the first 100 accounts closed over three years ago to demonstrate that the automated process is functioning."},{"kind":"TESTING","description":"Perform a quarterly audit of the archive to confirm no records older than three years remain, documenting any exceptions."},{"kind":"APPROVAL","description":"Secure sign‑off from the Data Protection Officer and Head of IT Operations on the policy change, control update, and system configuration."}],"suggested_owner":"Data Protection / Operations Lead","target_days":60,"dependencies":["IT Operations","Archive System team","Legal"],"expected_evidence":"Updated Data Retention Policy document, revised C‑KYC‑08 control text, Archive System configuration screenshot showing three‑year retention rule, deletion log report for pilot accounts, quarterly audit report, approval sign‑off records.","verification_method":"Compliance will conduct an annual data‑retention audit comparing archive timestamps against the three‑year rule and verify that the system configuration matches the documented policy.","touches_production":true}]}', 'groq', 'openai/gpt-oss-120b', 1116, 1739, '2026-10-08 06:25:08.371671+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('a79e3121d3724a67786fe38eff7b04c78d32db14fce3b1b1866555e0076a9111', 'remediation', '{"plans":[{"finding_id":"F1","root_cause":"No documented control or process exists to deliver the required annual data protection awareness training for employees handling personal data, resulting in a missing control gap.","actions":[{"kind":"POLICY_UPDATE","description":"Draft and approve a Data Protection Training Policy that mandates annual awareness training for all employees handling personal data, assigning responsibility to HR and the Data Protection Officer."},{"kind":"CONTROL_CHANGE","description":"Create control C-DP-01 \"Annual Data Protection Awareness Training\" in the compliance register with frequency P1Y, owner HR/Data Protection, and link to the new policy."},{"kind":"PROCESS_CHANGE","description":"Design a training curriculum and enrollment workflow in the LMS, ensuring all relevant staff are automatically enrolled each year."},{"kind":"TECHNOLOGY_CHANGE","description":"Configure the Learning Management System to auto‑assign the training, track completion status, and generate quarterly compliance reports."},{"kind":"EVIDENCE_COLLECTION","description":"Collect LMS completion reports and retain signed acknowledgment forms as evidence of training delivery for each employee."},{"kind":"APPROVAL","description":"Obtain sign‑off from the Chief Compliance Officer and Data Protection Officer on the policy, control entry, and evidence collection process."}],"suggested_owner":"Head of Human Resources (in partnership with the Data Protection Officer)","target_days":60,"dependencies":["LMS Administration Team","IT Security","Compliance Management Team"],"expected_evidence":"Approved Data Protection Training Policy, control C-DP-01 entry in the control register, LMS completion reports for all relevant employees, and signed acknowledgment records.","verification_method":"Internal audit will review the policy, verify the control entry, sample LMS reports for completeness, and interview a subset of employees to confirm training receipt; audit will also check that the annual schedule is enforced.","touches_production":true},{"finding_id":"F2","root_cause":"Existing control C-KYC-09 only addresses AML alert review and filing, leaving the broader governance obligation of overall compliance responsibility unassigned, resulting in partial coverage.","actions":[{"kind":"POLICY_UPDATE","description":"Update the Governance Framework to explicitly assign overall compliance responsibility to the Chief Compliance Officer and the Governance Committee."},{"kind":"CONTROL_CHANGE","description":"Create control C-GOV-01 \"Compliance Oversight and Accountability\" with continuous frequency, owner Chief Compliance Officer, covering all regulatory obligations."},{"kind":"PROCESS_CHANGE","description":"Establish quarterly compliance review meetings, produce a compliance dashboard, and circulate minutes to senior management and the Board."},{"kind":"EVIDENCE_COLLECTION","description":"Compile the updated governance policy, responsibility matrix, meeting minutes, and screenshots of the compliance dashboard as evidence."},{"kind":"TESTING","description":"Conduct an internal audit to verify that the new control is operating, responsibilities are documented, and review meetings are held as scheduled."},{"kind":"APPROVAL","description":"Secure Board approval of the revised governance framework and the new compliance oversight control."}],"suggested_owner":"Chief Compliance Officer","target_days":45,"dependencies":["Risk Management Team","IT Business Intelligence","Board Secretariat"],"expected_evidence":"Revised Governance Framework document, control C-GOV-01 entry, responsibility matrix linking obligations to owners, quarterly meeting minutes, and compliance dashboard reports.","verification_method":"Compliance audit will assess the presence of the responsibility matrix, review meeting minutes for quarterly frequency, validate dashboard data, and test that the control C-GOV-01 is logged and monitored in the compliance system.","touches_production":false}]}', 'groq', 'openai/gpt-oss-120b', 1017, 1466, '2026-10-08 06:25:11.857894+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('6249824b9540c3c9d36ff30b3d7387fda72d907cba0ef411e95aac3802e5cc33', 'change_classification', '{"changes":[{"pair_id":"3.2","category":"EDITORIAL","is_material":false,"summary":"Wording changed but meaning identical; both state the Board reviews the KYC policy at least once a year.","old_value":null,"new_value":null,"confidence":1.0},{"pair_id":"6.2","category":"FREQUENCY_CHANGED","is_material":true,"summary":"Review frequency tightened from six months to three months.","old_value":"six months","new_value":"three months","confidence":1.0},{"pair_id":"7.1","category":"FREQUENCY_CHANGED","is_material":true,"summary":"KYC update frequency for high‑risk customers tightened from every two years to every year.","old_value":"every two years","new_value":"every year","confidence":1.0},{"pair_id":"11.2","category":"DEADLINE_CHANGED","is_material":true,"summary":"Alert closure deadline reduced from 30 days to 15 days.","old_value":"30 days","new_value":"15 days","confidence":1.0}]}', 'groq', 'openai/gpt-oss-120b', 894, 867, '2026-10-08 06:31:01.548286+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('6031d23b7cfd034de3ddd3ce7fe52f37d24a482df6410a589322142216a3dcc8', 'applicability', '{"decisions":[{"obligation_id":"O1","decision":"APPLICABLE","rationale":"The bank offers corporate accounts and retail deposits, which involve account-based relationships requiring customer due diligence under the obligation.","confidence":1.0},{"obligation_id":"O2","decision":"UNCERTAIN","rationale":"The bank profile does not specify whether it serves legal entity customers or beneficial owners holding more than 10 per cent ownership interest.","confidence":0.9}]}', 'gemini', 'gemini-3.5-flash-lite', 444, 148, '2026-10-08 06:31:16.287293+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('d111a0a8c570c895aa69ffbd9351642b1a8f1df9b55891d555fc3e655dfc005f', 'control_mapping', '{"mappings":[{"obligation_id":"O1","judgements":[{"control_key":"C-KYC-11","relation":"PARTIAL","coverage":0.5,"confidence":0.95,"control_quote":"alerts are investigated and closed within 30 days","reason":"Deadline is 30 days, longer than required 15 days"},{"control_key":"C-KYC-09","relation":"PARTIAL","coverage":0.3,"confidence":0.9,"control_quote":"Alerts escalated as suspicious are reviewed by the Principal Officer and Suspicious Transaction Reports are filed ... within seven working days of the conclusion","reason":"Provides review of alerts but does not specify closure within 15 days of generation"},{"control_key":"C-KYC-06","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"Control relates to periodic KYC updates, not alert review/closure"},{"control_key":"C-IT-04","relation":"NONE","coverage":0.0,"confidence":0.99,"control_quote":null,"reason":"Control concerns patch management, unrelated to alert review"}]}]}', 'groq', 'openai/gpt-oss-120b', 956, 863, '2026-10-08 06:32:05.074073+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('f7ac628715aa8fb606b60db76882e6ddeb7dc862bd958cd2a721ec9a329301c0', 'cluster_confirmation', '{"groups":[{"group_id":"G0","equivalent":false,"topic":"Diverse compliance and record keeping obligations","summary":"This group mixes unrelated obligations including anti-tipping-off rules, log retention limits, record archiving periods, and secure storage requirements.","shared_control_suggestion":null,"confidence":0.95},{"group_id":"G1","equivalent":false,"topic":"Governance structures and policy reviews","summary":"This group combines distinct governance requirements such as appointing specific officers, constituting committees, and annual board-level policy reviews.","shared_control_suggestion":null,"confidence":0.9},{"group_id":"G2","equivalent":true,"topic":"Periodic staff training","summary":"Members require the bank to conduct mandatory training for employees handling specific operational or regulatory domains on an annual basis.","shared_control_suggestion":"Establish an enterprise-wide annual compliance and data protection training program covering both AML/KYC and data privacy topics.","confidence":0.95},{"group_id":"G3","equivalent":false,"topic":"Audits, testing, and reviews","summary":"This group includes a heterogeneous mix of quarterly backup restoration tests, internal audit compliance checks, annual IS audits, and vulnerability assessments.","shared_control_suggestion":null,"confidence":0.9},{"group_id":"G4","equivalent":false,"topic":"Regulatory reporting and notifications","summary":"This group aggregates various reporting obligations to authorities with widely differing timelines and triggers, such as STRs, CTRs, breach notifications, and officer appointments.","shared_control_suggestion":null,"confidence":0.95},{"group_id":"G5","equivalent":false,"topic":"Transaction monitoring and system reviews","summary":"This group groups automated transaction monitoring setup, alert review timelines, and user access reviews, which represent different operational controls.","shared_control_suggestion":null,"confidence":0.85}]}', 'gemini', 'gemini-3.5-flash-lite', 1224, 560, '2026-10-08 06:32:24.288536+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('3b9de89d3c27110f40101e2a84485f832e54fd7874355cb1d3bfb0948322041e', 'conflict_detection', '{"pairs":[{"pair_id":"P0","is_potential_conflict":true,"conflict_type":"DURATION_MISMATCH","reason":"A requires that personal data in system and application logs be deleted after no more than 90 days, while B requires those same logs be retained for at least 180 days. The required retention periods are mutually exclusive for the same data.","resolution_hint":"Seek a legal exemption or carve‑out; if none exists, the organization must reconcile the conflict, e.g., by applying the longer retention only where expressly permitted by another law.","applicability_overlap":"Both obligations target personal data contained in system and application logs.","confidence":0.95},{"pair_id":"P1","is_potential_conflict":false,"conflict_type":"NONE","reason":"A governs general system and application logs, mandating deletion after 90 days. B governs the audit trail of V‑CIP sessions, mandating retention for five years. The data sets and purposes are distinct, so the requirements do not clash.","resolution_hint":null,"applicability_overlap":"A applies to all system/application logs; B applies only to V‑CIP session audit trails, which are separate records.","confidence":0.9},{"pair_id":"P2","is_potential_conflict":false,"conflict_type":"NONE","reason":"A limits retention of system and application logs to 90 days, while B requires preservation of customer identification records for five years after the relationship ends. The obligations cover different types of records, so there is no direct conflict.","resolution_hint":null,"applicability_overlap":"A concerns general logs; B concerns identification records, so they do not overlap on the same data.","confidence":0.9}]}', 'groq', 'openai/gpt-oss-120b', 984, 832, '2026-10-08 06:33:04.78359+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('275c1204975b248b42aabed75c1b46b0c3b3ac44b7134dca4841e3804e4935fd', 'obligation_extraction', '{"obligations":[{"section_id":"3.2","requirement_text":"The Board must review the KYC policy at least once a year.","source_quote":"The Board shall review the KYC policy not less than once a year.","modality":"MUST","obligation_type":"GOVERNANCE","subject":"Board","action":"review the KYC policy","condition":null,"frequency_text":"not less than once a year","deadline_text":null,"applicability":{"entity_types":[],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":null,"required_evidence":[{"description":"Board meeting minutes documenting the policy review","evidence_type":"DOCUMENT"},{"description":"Updated KYC policy version","evidence_type":"DOCUMENT"}],"ambiguity_note":null,"self_confidence":0.99},{"section_id":"6.2","requirement_text":"The institution must review the risk categorisation of customers at least once every three months.","source_quote":"The risk categorisation of customers shall be reviewed at least once in three months.","modality":"MUST","obligation_type":"RISK_ASSESSMENT","subject":"Risk categorisation of customers","action":"be reviewed","condition":null,"frequency_text":"at least once in three months","deadline_text":null,"applicability":{"entity_types":[],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":null,"required_evidence":[{"description":"Risk categorisation review report","evidence_type":"DOCUMENT"},{"description":"Updated risk categorisation records","evidence_type":"DOCUMENT"}],"ambiguity_note":null,"self_confidence":0.99},{"section_id":"7.1","requirement_text":"The RE must carry out periodic updation of KYC for high risk customers at least once a year.","source_quote":"The RE shall carry out periodic updation of KYC at least once every year for high risk customers.","modality":"MUST","obligation_type":"CUSTOMER_DUE_DILIGENCE","subject":"RE","action":"carry out periodic updation of KYC","condition":"for high risk customers","frequency_text":"at least once every year","deadline_text":null,"applicability":{"entity_types":[],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":null,"required_evidence":[{"description":"Updated KYC records for high risk customers","evidence_type":"DOCUMENT"},{"description":"Log of KYC update activities","evidence_type":"DOCUMENT"}],"ambiguity_note":null,"self_confidence":0.99},{"section_id":"8.3","requirement_text":"The audit trail of each V-CIP session must be retained for five years.","source_quote":"The audit trail of each V-CIP session, including the geo-location and timestamp of the customer, shall be retained for a period of five years.","modality":"MUST","obligation_type":"RECORD_RETENTION","subject":"Audit trail of each V-CIP session","action":"be retained","condition":null,"frequency_text":null,"deadline_text":"for a period of five years","applicability":{"entity_types":[],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":null,"required_evidence":[{"description":"Stored audit logs of V-CIP sessions","evidence_type":"DOCUMENT"},{"description":"Retention schedule showing five‑year period","evidence_type":"DOCUMENT"}],"ambiguity_note":null,"self_confidence":0.99},{"section_id":"11.2","requirement_text":"Every alert generated by the transaction monitoring system must be reviewed and closed within 15 days of its generation.","source_quote":"Every alert generated by the transaction monitoring system shall be reviewed and closed within 15 days of its generation.","modality":"MUST","obligation_type":"MONITORING","subject":"Every alert generated by the transaction monitoring system","action":"be reviewed and closed","condition":null,"frequency_text":null,"deadline_text":"within 15 days of its generation","applicability":{"entity_types":[],"products":[],"customer_segments":[],"thresholds":[]},"responsible_function":null,"required_evidence":[{"description":"Alert handling log showing review and closure timestamps","evidence_type":"DOCUMENT"},{"description":"Report of alerts closed within the 15‑day window","evidence_type":"DOCUMENT"}],"ambiguity_note":null,"self_confidence":0.99}]}', 'groq', 'openai/gpt-oss-120b', 1388, 2469, '2026-10-08 06:31:07.4257+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('39611b8a96dc7c2708171dbca2e76cb9412d7b445b5ef02e385b03d9740b23e9', 'obligation_verification', '{"results":[{"candidate_id":"Candidate 0","entailed":true,"reason":"The source text states that the Board shall review the KYC policy not less than once a year, perfectly matching the extracted obligation."},{"candidate_id":"Candidate 1","entailed":true,"reason":"The source text states that the risk categorisation shall be reviewed at least once in three months, matching the obligation."},{"candidate_id":"Candidate 2","entailed":true,"reason":"The source text mandates the RE to carry out periodic updation of KYC at least once every year for high risk customers."},{"candidate_id":"Candidate 3","entailed":true,"reason":"The source text requires the audit trail of each V-CIP session to be retained for a period of five years."},{"candidate_id":"Candidate 4","entailed":true,"reason":"The source text specifies that every alert generated by the transaction monitoring system must be reviewed and closed within 15 days of generation."}]}', 'gemini', 'gemini-3.5-flash-lite', 604, 293, '2026-10-08 06:31:12.293096+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('2bddc3655ae547a8bb2c58a85f160134e60ab0ba91f01138fe5e8295319d7e13', 'control_mapping', '{"mappings":[{"obligation_id":"O1","judgements":[{"control_key":"C-KYC-05","relation":"PARTIAL","coverage":0.5,"confidence":0.95,"control_quote":"reviews the risk categorisation (low, medium, high) of all customers once in six months","reason":"The control reviews risk categorisation for all customers, matching the scope, but the frequency is ''once in six months'' which is less frequent than the required ''at least once every three months''."},{"control_key":"C-KYC-06","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"This control addresses periodic KYC updation based on risk tiers, not the specific review of risk categorisation itself."},{"control_key":"C-IT-02","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"This control concerns user access rights to systems, not customer risk categorisation."},{"control_key":"C-KYC-10","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"This control concerns Cash Transaction Report submission, not customer risk categorisation."}]},{"obligation_id":"O2","judgements":[{"control_key":"C-KYC-06","relation":"PARTIAL","coverage":0.5,"confidence":0.95,"control_quote":"high risk every two years","reason":"The control covers high-risk customers but sets the updation frequency to ''every two years'', which is less frequent than the required ''at least once every year''."},{"control_key":"C-KYC-12","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"This control is about staff training, not customer KYC updation."},{"control_key":"C-KYC-01","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"This control is about policy approval and review, not customer KYC updation."},{"control_key":"C-KYC-13","relation":"NONE","coverage":0.0,"confidence":0.9,"control_quote":null,"reason":"This control is an audit of compliance, not the execution of the KYC updation itself."}]},{"obligation_id":"O3","judgements":[{"control_key":"C-KYC-08","relation":"PARTIAL","coverage":0.6,"confidence":0.8,"control_quote":"Transaction records and customer identification records are archived and retained for five years","reason":"The control retains records for five years, matching the deadline, but explicitly lists ''Transaction records and customer identification records'' without explicitly mentioning V-CIP session audit trails, which may be a distinct data type."},{"control_key":"C-IT-03","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"This control retains logs for 180 days, which is far shorter than the required five years, and applies to privileged sessions, not V-CIP."},{"control_key":"C-KYC-07","relation":"PARTIAL","coverage":0.4,"confidence":0.85,"control_quote":"Every video KYC session is recorded end-to-end and stored in encrypted storage","reason":"The control ensures V-CIP sessions are recorded and stored, but does not specify a retention period, so it does not confirm the five-year requirement."},{"control_key":"C-KYC-09","relation":"NONE","coverage":0.0,"confidence":0.95,"control_quote":null,"reason":"This control concerns STR filing, not V-CIP audit trail retention."}]}]}', 'groq#2', 'qwen/qwen3.8-27b', 1551, 1195, '2026-10-08 06:31:19.602292+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('27e9564137f237930ece064ec581dfe511f70543f8984be8d8149b414ce6612b', 'evidence_assessment', '{"verdicts":[{"criterion_id":"K1","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt provides aggregate closure statistics but no log entries with review and closure timestamps.","confidence":0.9},{"criterion_id":"K2","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"The excerpt reports closure within 30 days and median 18 days, but gives no data on the 15‑day window.","confidence":0.9},{"criterion_id":"K3","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"No system architecture documentation is presented in the excerpt.","confidence":0.9},{"criterion_id":"K4","verdict":"INSUFFICIENT","evidence_id":null,"quote":null,"rationale":"While the excerpt shows alerts being generated and closed, it does not explicitly confirm system deployment or operational status documentation.","confidence":0.9}]}', 'groq', 'openai/gpt-oss-120b', 738, 573, '2026-10-08 06:32:08.662671+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('c6e51aa6e137c693937f7e3eb07d84fb51a2b5cfb7a1ffaed028c28fae4556d3', 'remediation', '{"plans":[{"finding_id":"F1","root_cause":"The C-KYC-06 tracker is configured to flag high‑risk customers every two years, which does not meet the regulatory requirement of an annual KYC update, and branch SOP allows 60 days for completion, creating a timing gap.","actions":[{"kind":"CONTROL_CHANGE","description":"Change C-KYC-06 tracker frequency for high‑risk customers from every 2 years to annually (P1Y) in the Core Banking System configuration."},{"kind":"PROCESS_CHANGE","description":"Update Retail Operations branch SOP to complete high‑risk KYC updates within 30 days of the annual flag."},{"kind":"POLICY_UPDATE","description":"Revise the KYC policy to state that high‑risk customers must be re‑validated at least once per year."},{"kind":"EVIDENCE_COLLECTION","description":"Produce monthly tracker reports for three consecutive months showing flagged high‑risk customers and documented KYC completions within 30 days."},{"kind":"TESTING","description":"Internal audit to sample flagged high‑risk customers and verify KYC was updated within the 12‑month regulatory window."},{"kind":"APPROVAL","description":"Obtain sign‑off from the Chief Compliance Officer on the updated control configuration and policy amendment."}],"suggested_owner":"Head - Retail Operations","target_days":45,"dependencies":["Core Banking System Team","Retail Operations Branches","Compliance Policy Team"],"expected_evidence":"Updated Core Banking System tracker settings, revised SOP document, amended KYC policy, three months of tracker reports, audit sampling report, and CCO approval memo.","verification_method":"Compliance audit will re‑run the tracker query and sample KYC records to confirm annual flagging and 30‑day completion for high‑risk customers.","touches_production":true},{"finding_id":"F2","root_cause":"C‑KYC‑05 is scheduled to run every six months, which is less frequent than the regulatory mandate of a quarterly (every three months) risk‑categorisation review, resulting in partial coverage.","actions":[{"kind":"CONTROL_CHANGE","description":"Modify the AML Risk Engine schedule for C‑KYC‑05 to execute risk‑categorisation reviews every 3 months (P3M) instead of every 6 months."},{"kind":"PROCESS_CHANGE","description":"Update the AML team SOP to conduct and document risk‑categorisation reviews quarterly."},{"kind":"POLICY_UPDATE","description":"Amend the risk‑assessment policy to reflect the quarterly review requirement for all customer risk categories."},{"kind":"EVIDENCE_COLLECTION","description":"Extract and archive risk‑categorisation change logs for a 3‑month period demonstrating quarterly reviews."},{"kind":"TESTING","description":"Perform compliance testing on a random sample of customers to confirm their risk category was reviewed within the 90‑day window."},{"kind":"APPROVAL","description":"Secure formal approval from the Head of AML and the Risk Management Committee for the schedule and policy changes."}],"suggested_owner":"Head - AML","target_days":30,"dependencies":["AML Risk Engine Team","IT Change Management","Risk Management Committee"],"expected_evidence":"Updated AML Risk Engine scheduler settings, revised AML SOP, updated risk‑assessment policy, 3‑month change‑log extract, testing results report, and approval minutes from AML and Risk Committee.","verification_method":"Quarterly compliance review will query the risk engine logs and sample customer records to verify that risk categorisation was reviewed within 90 days as required.","touches_production":true}]}', 'groq', 'openai/gpt-oss-120b', 1113, 1569, '2026-10-08 06:32:13.533612+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('f4355034bbe69a9fa25f51e33d27339b01b4011a3ff5499683f8c4984e189afb', 'remediation', '{"plans":[{"finding_id":"F1","root_cause":"Control C-KYC-08 is configured to retain general transaction and customer identification records for five years, but it does not explicitly capture or retain the specific V-CIP session audit trail elements required by obligation 8.3, namely the geo-location and timestamp of the customer during the session. This results in a 69% coverage gap where the specific V-CIP metadata is not guaranteed to be preserved for the full five-year period.","actions":[{"kind":"CONTROL_CHANGE","description":"Update the retention policy configuration in the Archive System to explicitly include V-CIP session logs, specifically ensuring that geo-location and timestamp fields are mapped to the five-year retention schedule."},{"kind":"TECHNOLOGY_CHANGE","description":"Modify the V-CIP application logging module to ensure that geo-location and timestamp data are written to the audit trail in a format compatible with the Archive System''s ingestion pipeline."},{"kind":"TESTING","description":"Perform a data integrity test to verify that V-CIP session records, including geo-location and timestamps, are successfully archived and remain accessible for the full five-year retention period."},{"kind":"EVIDENCE_COLLECTION","description":"Generate a sample report of archived V-CIP sessions from the past 12 months to demonstrate that geo-location and timestamp fields are present and retained."}],"suggested_owner":"Head - IT Operations","target_days":45,"dependencies":["V-CIP Application Team","Archive System Administration"],"expected_evidence":"Updated retention configuration logs, test results confirming five-year retention of V-CIP geo-location and timestamp data, and a sample archived session report.","verification_method":"Compliance will re-test by sampling V-CIP sessions from the archive system to verify that geo-location and timestamp fields are present and that the retention period is set to five years.","touches_production":true}]}', 'groq#2', 'qwen/qwen3.8-27b', 839, 491, '2026-10-08 06:32:20.858113+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('a03b81e20f675af5934217405ca9fa7adc20d70759f7b17bce293585bc88a48f', 'conflict_detection', '{"pairs":[{"pair_id":"P3","is_potential_conflict":true,"conflict_type":"DURATION_MISMATCH","reason":"A requires that system and application logs be retained for no more than 90 days (SDPA 2.2), while B requires maintaining all transaction records for at least five years (1825 days) (SRA 9.1). The two obligations differ in both duration and modality (must delete vs must retain) and could overlap if the logs contain transaction data.","resolution_hint":"If logs are not considered transaction records, retain them for 90 days and keep transaction records for five years. If they overlap, the stricter requirement (retain for five years) can satisfy SRA, while non‑transaction log data should still be deleted after 90 days.","applicability_overlap":"Both obligations relate to retention of data that may be stored in system/application logs, potentially covering the same records.","confidence":0.78},{"pair_id":"P4","is_potential_conflict":false,"conflict_type":"NONE","reason":"A permits erasing personal data up to three years after account closure unless another law requires longer retention (SDPA 2.1). B mandates preserving customer identification records for five years after the business relationship ends (SRA 9.2). The exception in A allows compliance with B''s five‑year requirement, so no conflict arises.","resolution_hint":null,"applicability_overlap":"Both apply to customer identification data after the relationship has ended.","confidence":0.9},{"pair_id":"P5","is_potential_conflict":false,"conflict_type":"NONE","reason":"B allows erasing personal data after three years unless another law requires longer retention (SDPA 2.1). A requires keeping transaction records for at least five years (SRA 9.1). Because A is a legal requirement, B''s exception permits the longer five‑year retention, eliminating any conflict.","resolution_hint":null,"applicability_overlap":"Both obligations concern the same customer data after the account is closed or the transaction is completed.","confidence":0.9}]}', 'groq', 'openai/gpt-oss-120b', 1009, 1116, '2026-10-08 06:33:08.065794+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('f363249c6c967399faab79a324b481cf33b93b0fb0d4f74523e292da9da65304', 'conflict_detection', '{"pairs":[{"pair_id":"P6","is_potential_conflict":true,"conflict_type":"DURATION_MISMATCH","reason":"A requires retaining the V‑CIP audit trail for five years (1825 days) while B mandates erasing personal data within three years (1095 days) after account closure, creating a clash unless the exception in B applies.","resolution_hint":"B includes an exception \"unless retention is required under any other law\"; compliance with A can be justified under that clause.","applicability_overlap":"Both obligations concern personal data contained in audit logs for a customer.","confidence":0.85},{"pair_id":"P7","is_potential_conflict":false,"conflict_type":"NONE","reason":"A''s minimum retention of 180 days is well within B''s maximum deletion window of three years, so both requirements can be satisfied simultaneously.","resolution_hint":null,"applicability_overlap":"Both refer to customer logs/personal data.","confidence":0.9},{"pair_id":"P8","is_potential_conflict":false,"conflict_type":"NONE","reason":"A limits log retention to 90 days, while B only requires that recordings be stored securely; the obligations address different dimensions (duration vs security) and do not conflict.","resolution_hint":null,"applicability_overlap":"Both apply to system/application logs, but one governs retention period and the other storage security, allowing concurrent compliance.","confidence":0.9}]}', 'groq', 'openai/gpt-oss-120b', 983, 1025, '2026-10-08 06:33:12.409072+00', 0, NULL, NULL);
INSERT INTO public.llm_cache VALUES ('3916211a5b817b2ed31f8cae8008b555f40b531efc41c7d9522a20ca9d5d0d33', 'conflict_detection', '{"pairs":[{"pair_id":"P9","is_potential_conflict":false,"conflict_type":"NONE","reason":"Obligation A (SDPA 2.2) imposes a maximum retention limit of 90 days for personal data in logs, while Obligation B (SRA 8.2) requires that recordings be stored in a ''safe and secure manner''. These are compatible: an entity can store data securely for up to 90 days and then delete it. There is no requirement in B to retain data indefinitely or beyond 90 days, so complying with A does not breach B.","resolution_hint":"Store the data securely for the duration permitted by A (max 90 days) and ensure the storage mechanism meets the security standards of B.","applicability_overlap":"Both obligations apply to the storage of recorded data or logs, but A limits duration while B specifies security quality.","confidence":0.95},{"pair_id":"P10","is_potential_conflict":false,"conflict_type":"NONE","reason":"Obligation A (SDPA 3.1) requires notification of a data breach within 72 hours, while Obligation B (SRA 4.2) requires communicating the Principal Officer''s details to the FIU within 30 days of appointment. These obligations trigger on completely different events (breach vs. appointment) and involve different data subjects and recipients. There is no overlap in the activity or data, so no conflict exists.","resolution_hint":null,"applicability_overlap":"No overlap; the obligations address distinct regulatory events (breach notification vs. officer registration).","confidence":0.98},{"pair_id":"P11","is_potential_conflict":false,"conflict_type":"NONE","reason":"Obligation A (SRA 4.2) requires communicating the Principal Officer''s details to the FIU within 30 days of appointment, while Obligation B (SDPA 3.1) requires notifying the Authority of a data breach within 72 hours. These are distinct obligations triggered by different events (appointment vs. breach) and directed at different authorities (FIU vs. Data Protection Authority). There is no conflict in compliance.","resolution_hint":null,"applicability_overlap":"No overlap; the obligations address distinct regulatory events (officer registration vs. breach notification).","confidence":0.98}]}', 'groq#2', 'qwen/qwen3.8-27b', 855, 595, '2026-10-08 06:33:13.875841+00', 0, NULL, NULL);
